"""
Generateur du CATALOGUE MAITRE de l'ECU EDC15C2 / PSA 2.2 4HX (ref 0 281 010 877, full mux).

Le document produit (analyse_edc15c2_4hx/CATALOGUE_MAITRE.md) est REGENERABLE :
relancer ce script apres chaque trouvaille met le catalogue a jour sans ressaisie.

Sources :
  - edc.bin                     (512 Ko)
  - clean.asm                   (desassemblage annote, preuves par n de ligne)
  - annotation_datensatz.csv    (courbes 1-D decodees)
  - annotation_cartes_2D.csv    (cartes 2-D decodees)
"""
import struct, re, csv, datetime, sys
sys.path.insert(0, '/home/user/outils')
from catalogue_extras import AXES, nom_axe, nom_carte, etendue_c, kelvin_c, lignes_io, SCHEMAS

BIN = '/home/user/edc.bin'
OUT = '/home/user/analyse_edc15c2_4hx/CATALOGUE_MAITRE.md'
TBL, BASE = 0x61400, 0x60000

d = open(BIN, 'rb').read()
vals = {0x1400 + i: struct.unpack_from('<H', d, TBL + i)[0] for i in range(0, 0x61E30 - TBL, 2)}
uniq = sorted(set(vals.values()))
nxt = {v: (uniq[k + 1] if k + 1 < len(uniq) else None) for k, v in enumerate(uniq)}

names = {}
for line in open('/home/user/clean.asm', encoding='latin-1'):
    m = re.match(r'^(byte|word)_([0-9A-F]{4,5}):\s+ds', line)
    if m:
        names[int(m.group(2), 16)] = m.group(1).lower() + '_' + m.group(2)


