STRUCTS = sorted(_par_struct.items(), key=lambda kv: -len(kv[1]))


try:
    SWC = list(csv.DictReader(open('/home/user/analyse_edc15c2_4hx/switchs_contenu.csv'), delimiter=';'))
except Exception:
    SWC = []
SW_SW = [x for x in SWC if x['classe'] == 'SWITCH']
SW_DO = [x for x in SWC if x['classe'] == 'DONNEE']
# ------------------------------------------------------------------ unites connues
# 'lu' = etabli par le binaire ; 'util' = donne par l'utilisateur ; 'inf' = inference forte
UNIT = {
    'word_C42E': ('régime moteur', 'tr/min', 'lu+plage 0-6000'),
    'word_C3E6': ('débit d’air', 'mg/s (axe ×10)', 'util'),
    # ERRATA 56 : ces trois variables etaient annotees « masse d'air par tour (mg x10) »
    # par inference de PLAGE. L'etape 13 prouve la chaine capteur -> C3xx : ce sont des
    # TEMPERATURES. Une plage ne prouve rien : 2200-4300 est aussi 220-430 mg/tour.
    'word_C3D2': ('température liquide de refroidissement', 'K ×10', 'lu (chaîne 0x318)'),
    'word_C3BA': ('température air d’admission', 'K ×10', 'lu (chaîne 0x30E)'),
    'word_C3B0': ('température gasoil', 'K ×10', 'lu (chaîne 0x310)'),
    'word_C5A4': ('masse d’air par tour', 'mg ×10', 'inf'),
    'word_C5A8': ('masse d’air par tour', 'mg ×10', 'inf (étape 50)'),
    'word_C6A2': ('grandeur de charge', '0…100 % (×100)', 'lu (plage 0-10000)'),
    'word_C3C2': ('rapport cyclique (RCO ?)', '0…1000', 'inf'),
}

def sv(x):
    return x - 0x10000 if x >= 0x8000 else x

def w(ea, o):
    return struct.unpack_from('<H', d, BASE + (ea - 0xE0000) + o)[0]

def isram(x):
    return 0x8000 <= x <= 0xFFFF

def read1(ea, lim):
    w0, n = w(ea, 0), w(ea, 2)
    if not isram(w0) or not (2 <= n <= 128):
        return None
    if lim is not None and 4 + 4 * n > lim:
        return None
    ax = [w(ea, 4 + 2 * k) for k in range(n)]
    vv = [w(ea, 4 + 2 * n + 2 * k) for k in range(n)]
    return dict(w0=w0, n=n, ax=ax, vv=vv, size=4 + 4 * n)

def read2(ea, lim):
    ty, ny = w(ea, 0), w(ea, 2)
    if not isram(ty) or not (2 <= ny <= 64):
        return None
    p = 4 + 2 * ny
    tx, nx = w(ea, p), w(ea, p + 2)
    if not isram(tx) or not (2 <= nx <= 64):
        return None
    size = p + 4 + 2 * nx + 2 * ny * nx
    if lim is not None and size > lim:
        return None
    axY = [w(ea, 4 + 2 * k) for k in range(ny)]
    axX = [w(ea, p + 4 + 2 * k) for k in range(nx)]
    grid = [w(ea, p + 4 + 2 * nx + 2 * k) for k in range(ny * nx)]
    return dict(ty=ty, ny=ny, tx=tx, nx=nx, axY=axY, axX=axX, grid=grid, size=size)

def fmtlist(l, maxi=8):
    s = ', '.join(str(sv(x)) for x in l[:maxi])
    if len(l) > maxi:
        s += ', … (%d pts)' % len(l)
    return s

def nm(a):
    return names.get(a, '—')

# ------------------------------------------------------------------ collecte
C1, C2, reserved, scalar, other = [], [], [], [], []
ambig = 0
for h, v in sorted(vals.items()):
    ea = 0xE0000 + v
    lim = (nxt[v] - v) if nxt[v] is not None else None
    w0 = w(ea, 0)
    # 1) blocs reserves : en-tete 0xFFFE, contenu nul
    if w0 == 0xFFFE and lim is not None and sum(
            1 for k in range(2, lim)
            if d[BASE + (ea - 0xE0000) + k] != 0) <= 4:
        reserved.append((h, ea, lim)); continue
    e1 = read1(ea, lim)
    e2 = read2(ea, lim)
    # 2) on prefere le decodage dont la taille EGALE celle du bloc
    s1 = e1['size'] if e1 else None
    s2 = e2['size'] if e2 else None
    pick = None
    if lim is not None and e2 and s2 == lim and s1 != lim:
        pick = 2
    elif lim is not None and e1 and s1 == lim:
        pick = 1
    elif lim is not None and e2 and s2 == lim:
        pick = 2
    elif e1 and not e2:
        pick = 1
    elif e2 and not e1:
        pick = 2
    elif e1 and e2:
        pick = 1; ambig += 1
    if pick == 1:
        C1.append((h, ea, lim, e1)); continue
    if pick == 2:
        C2.append((h, ea, lim, e2)); continue
    if lim == 2:
        scalar.append((h, ea, w0)); continue
    other.append((h, ea, lim, w0))

# ------------------------------------------------------------------ gabarits complementaires
axisb = []          # [var][n][n valeurs] -> 4+2n, distinct de 4+4n
paramw = {}         # taille en mots -> nb de blocs  (petits blocs de parametres)
b32marker = {}
for h, v in sorted(vals.items()):
    ea = 0xE0000 + v
    lim = (nxt[v] - v) if nxt[v] is not None else None
    if lim is None:
        continue
    w0, n = w(ea, 0), w(ea, 2)
    if isram(w0) and 2 <= n <= 128 and 4 + 2 * n == lim and 4 + 4 * n != lim:
        axisb.append((h, ea, lim, w0, n, [w(ea, 4 + 2 * k) for k in range(n)]))
        continue
    if lim == 32:
        b32marker[w(ea, 18)] = b32marker.get(w(ea, 18), 0) + 1
    if lim % 2 == 0 and lim <= 40:
        paramw[lim // 2] = paramw.get(lim // 2, 0) + 1

# ------------------------------------------------------------------ usage par handle
USAGE = '/home/user/analyse_edc15c2_4hx/usage_handles_resume.csv'
usage = {}
try:
    for r in csv.DictReader(open(USAGE)):
        usage[int(r['handle'].replace('word_', ''), 16)] = r
except Exception:
    pass
sweep = []
for hh, r in usage.items():
    lo = [int(x, 16) for x in r['offsets_lus'].split()]
    if len(lo) >= 8 and lo[:4] == [0, 2, 4, 6]:
        sweep.append((hh, lo[-1], len(lo)))

# ------------------------------------------------------------------ consommateurs
CONS = '/home/user/analyse_edc15c2_4hx/consommateurs_handles.csv'
cons = []
try:
    cons = list(csv.DictReader(open(CONS)))
except Exception:
    pass
bycons = {}
for r in cons:
    bycons.setdefault(r['consommateur_principal'], []).append(r)

CONSMAP = {}
for r in cons:
    CONSMAP[r['handle']] = r['consommateur_principal']

def blocksize(h):
    v = vals.get(int(h.replace('word_', ''), 16))
    if v is None or nxt.get(v) is None:
        return None
    return nxt[v] - v

# ------------------------------------------------------------------ document
L = []
A = L.append
A('# CATALOGUE MAÎTRE — ECU Bosch EDC15C2 / PSA 2.2 4HX FAP')
