A('')
A('> **Document vivant.** Il est régénéré automatiquement à partir du binaire, du désassemblage et des')
A('> CSV d’annotation. Chaque trouvaille ajoute une ligne ou une nuance ; les affirmations retirées')
A('> restent visibles au § 9 (registre des erratas) pour ne pas être réintroduites par erreur.')
