A('étant l’entrée 0. **Offset fichier = `0x60000 + valeur`.** Le Datensatz dupliqué est à `0xF0000`')
A('(**offset fichier `0x70000`**).')
A('')
A('**Bornes de bloc.** Le bloc d’un handle va de sa valeur à la valeur suivante (ordre croissant).')
A('Méthode validée quatre fois indépendamment (étapes 48 à 51).')
A('')
