A('---')
A('')
A('## 2. Les gabarits d’enregistrement identifiés')
A('')
A('| type | gabarit | taille | preuve |')
A('|---|---|---|---|')
A('| **Courbe 1-D** | `[adresse variable][n][axe : n mots][valeurs : n mots]` | `4 + 4n` | **181 tailles exactes** sur 248 (étape 51) |')
A('| **Carte 2-D** | `[tagY][nY][axeY][tagX][nX][axeX][grille : nY×nX mots]` | `8 + 2nY + 2nX + 2·nY·nX` | **66 tailles exactes sur 66** (étape 51) |')
A('| **Paramètre scalaire** | un seul mot de calibration | 2 | blocs de 2 octets, étape 52 |')
