A('')
if usage:
    A('| | |')
    A('|---|---|')
    A('| handles du Datensatz avec au moins un accès identifiable | **%d / 1304** |' % len(usage))
    A('| dont **balayage séquentiel** (`0x00, 0x02, 0x04, 0x06…`) | **%d** |' % len(sweep))
    A('')
