A('')
A('### ★★★ Constat 5 — le Datensatz est **rangé par FONCTION CONSOMMATRICE**')
A('')
if bycons:
    A('En associant chaque accès du code à sa fonction englobante (`outils/consommateurs.py`), on obtient :')
    A('')
    A('| fonction | handles distincts | accès |')
    A('|---|---|---|')
    for f, lst in sorted(bycons.items(), key=lambda x: -len(x[1]))[:12]:
        A('| **`%s`** | %d | %d |' % (f, len(lst), sum(int(r['nb_acces']) for r in lst)))
    A('')
    A('**Chaque routine possède 7 à 19 blocs de calibration et rien d’autre.** La calibration n’est donc')
    A('**pas rangée par grandeur physique, mais par consommateur.** C’est le principe d’organisation du')
    A('Datensatz, et il donne une **méthode de nommage** : le rôle de la fonction nomme ses blocs.')
    A('')
