A('')
A('## 2 ter. ★ Le Datensatz est stocké en DEUX exemplaires complets')
A('')
A('**0xE0000-0xEBFFF et 0xF0000-0xFBFFF sont identiques à 14 octets près.** Vérifié octet par octet.')
A('Ce ne sont pas deux zones différentes : c’est **la même calibration, écrite deux fois**.')
A('')
A('### Les 14 octets qui diffèrent — les cinq seules différences')
A('')
A('| exemplaire E | exemplaire F | taille | E | F | lecture |')
A('|---|---|---|---|---|---|')
for r in DUPL:
    A('| `%s` | `%s` | %s | `%s` | `%s` | %s |' % (
        r['EA_exemplaire_E'], r['EA_exemplaire_F'], r['taille'],
        r['valeur_E'], r['valeur_F'], LECT_DUP.get(r['EA_exemplaire_E'], '')))
A('')
A('**Ce que ces cinq différences disent :**')
A('')
A('1. **`0xE0FF6` et `0xE0FFC` = deux champs de contrôle en tête du Datensatz.** Dans l’exemplaire E ils')
A('   portent des valeurs concrètes (`0xD33D` **deux fois**, puis `0xB20532C9`) ; dans l’exemplaire F,')
A('   les deux mots valent `0xC3C3` et `0x0000` — c’est-à-dire **le remplissage**, non renseigné.')
A('   **⇒ L’exemplaire E est la calibration active ; F est un miroir dont les champs de contrôle')
A('   n’ont pas été remplis.**')
A('2. **`0xEBCFC` = un second champ de contrôle en queue de Datensatz**, différent dans chaque')
A('   exemplaire — donc **il dépend bien des données**, ce qui est le comportement d’une somme de')
A('   contrôle. ⚠ **On sait donc OÙ sont les sommes de contrôle, mais toujours pas COMMENT elles sont')
A('   calculées** : 15 algorithmes testés (sommes, CRC-16 CCITT/XMODEM/IBM, CRC-32, compléments)')
A('   **sans succès**. C’est un progrès de localisation, pas une résolution.')
A('3. **`0xEBF1B` : l’octet passe de `0x57` (« W ») à `0x46` (« F »)** dans la chaîne')
A('   `__NWGDWPF1` / `__NFGDWPF1`. **Hypothèse (non prouvée)** : `F` = **FAP**, `W` = sans filtre.')
A('   Ce serait l’identifiant de la variante — cohérent avec un véhicule FAP dont le calculateur')
A('   contient aussi la calibration sans filtre.')
A('4. **`0xE434D` : un octet `0x23` → `0x03`** au milieu d’une structure. Différence de calibration')
A('   entre les deux variantes ; **laquelle est utilisée n’est pas établi**.')
A('')
A('### Ce que cela change pour tout le reste du catalogue')
A('')
A('**Rien, et c’est important** : la table de pointeurs de `0xE1400` est **identique dans les deux')
A('exemplaires**, et ses valeurs sont des **offsets relatifs** (0x100A … 0xBC38). Le même handle')
A('désigne donc **la même structure dans les deux exemplaires**. Toutes les adresses EA du catalogue')
A('sont données **dans l’exemplaire E** ; ajouter `0x10000` donne l’exemplaire F.')
A('')
A('*Preuve : `outils/tables_oubliees.py` → `duplication_datensatz.csv`.*')
A('')
A('---')
A('')
A('## 3. Inventaire des variables (les « tags »)')
A('')
A('Une même variable peut servir d’entrée à plusieurs enregistrements. Le nombre d’axes et la plage')
A('globale sont calculés automatiquement : **la plage est le premier indice d’identification**.')
A('')
A('| variable | axes (1-D / 2-D) | plage globale | grandeur | unité | statut |')
A('|---|---|---|---|---|---|')

agg = {}
for h, ea, lim, e in C1:
    a = agg.setdefault(e['w0'], [0, 0, 1e9, -1e9])
    a[0] += 1
    a[2] = min(a[2], sv(e['ax'][0])); a[3] = max(a[3], sv(e['ax'][-1]))
for h, ea, lim, e in C2:
    for t, ax in ((e['ty'], e['axY']), (e['tx'], e['axX'])):
        a = agg.setdefault(t, [0, 0, 1e9, -1e9])
        a[1] += 1
        a[2] = min(a[2], sv(ax[0])); a[3] = max(a[3], sv(ax[-1]))
for var, (k1, k2, lo, hi) in sorted(agg.items(), key=lambda x: -(x[1][0] + x[1][1])):
    U = UNIT.get(nm(var), ('?', '?', '?'))
    A('| **%s** | %d / %d | %s … %s | %s | %s | %s |' % (
        nm(var), k1, k2, lo, hi, U[0], U[1], U[2]))
A('')
A('---')
A('')
A('## 4. Courbes 1-D — table exhaustive (%d)' % len(C1))
A('')
A('`ID` = handle (`word_xxxx`), c’est **l’identifiant de stockage**. `EA` = adresse logique dans le')
A('Datensatz. Les valeurs sont données dans l’ordre des points de l’axe.')
A('')
A('**Nom explicite** : `Loi <grandeur d’entrée> → sortie`. Quand la sortie n’est pas identifiée,')
A('c’est écrit tel quel — **aucun nom inventé**.')
A('')
A('> ⚠ `—` dans la colonne « consommateur » signifie *non établi*, **pas « non consommée »**.')
A('')
A('| ID | EA | nom explicite | n | axe | axe en °C | valeurs | sortie observée | consommateur (si établi) |')
A('|---|---|---|---|---|---|---|---|---|')
for h, ea, lim, e in C1:
    t = nm(e['w0'])
    lo, hi = sv(e['ax'][0]), sv(e['ax'][-1])
    vv = e['vv']
    sortie = '%d … %d' % (min(sv(x) for x in vv), max(sv(x) for x in vv)) if vv else '?'
    A('| `%04X` | `0x%05X` | **Loi** %s → *sortie non identifiée* | %d | %d → %d | %s | %s | %s | %s |' % (
        h, ea, nom_axe(t), e['n'], lo, hi, etendue_c(t, lo, hi) or '—', fmtlist(vv), sortie,
        ('`%s`' % CONSMAP['word_%04X' % h]) if ('word_%04X' % h) in CONSMAP else '—'))
A('')
A('---')
A('')
A('## 5. Cartes 2-D — table exhaustive (%d)' % len(C2))
A('')
A('**Nom explicite** : `CARTE <lignes> × <colonnes>`. La **sortie** est décrite par sa *magnitude*')
A('observée (minimum et maximum de la grille), ce qui oriente sans affirmer.')
A('')
A('> ⚠ **La colonne « consommateur » ne doit pas être mal lue.** Un `—` signifie *non établi par notre')
A('> outil*, **PAS « non consommée »**. Les cartes sont lues par l’interpolateur à travers un handle')
A('> passé en paramètre — motif que `outils/usage_handles.py` ne détecte pas encore. Leur non-consommation')
A('> a d’ailleurs été **réfutée** dès l’étape 25.')
A('')
A('| ID | EA | nom explicite de la carte | dim. | Y | X | magnitude de sortie | consommateur (si établi) |')
A('|---|---|---|---|---|---|---|---|')
for h, ea, lim, e in C2:
    g = [sv(x) for x in e['grid']]
    A('| `%04X` | `0x%05X` | **CARTE %s** | %d×%d | %d → %d | %d → %d | %d … %d | %s |' % (
        h, ea, nom_carte(nm(e['ty']), nm(e['tx'])), e['ny'], e['nx'],
        sv(e['axY'][0]), sv(e['axY'][-1]), sv(e['axX'][0]), sv(e['axX'][-1]),
        min(g), max(g),
        ('`%s`' % CONSMAP['word_%04X' % h]) if ('word_%04X' % h) in CONSMAP else '—'))
A('')
