A('')
A('## 5 bis. Signification des axes — ce qui est prouvé, ce qui est supposé')
A('')
A('> ### ⚠ Règle de prudence (correction de l’étape 56)')
A('>')
A('> **Une plage de valeurs ne prouve JAMAIS une grandeur.** 2 200 … 4 300 est aussi bien une')
A('> température en K × 10 qu’une masse d’air en mg/tour × 10, ou un régime partiel. Les trois')
A('> variables `word_C3D2`, `word_C3BA`, `word_C3B0` avaient été annotées « masse d’air par tour »')
A('> **sur la seule foi de leur plage** : c’était faux (ERRATA 56).')
A('>')
A('> **Un axe n’est nommé que si la chaîne qui le produit est identifiée** — capteur → voie ADC →')
A('> courbe → variable de travail. La plage ne sert qu’à **vérifier la vraisemblance**, jamais à')
A('> conclure.')
A('')
A('**Convention établie (fournie par l’utilisateur, et vérifiée par recoupement) : les températures sont')
A('codées en KELVIN × 10.** Le contrôle est net : **2731 = 0 °C** et **3531 = 80 °C**.')
A('')
A('**C’est cette convention qui donne son sens à toute une famille d’axes :**')
A('')
A('| variable | plage d’axe | en Kelvin | **en °C** | grandeur | confiance |')
A('|---|---|---|---|---|---|')
for tag in ('word_C3D2', 'word_C3BA', 'word_C3B0', 'word_C5A4', 'word_C586'):
    a = AXES.get(tag)
    if not a:
        continue
    rng = {'word_C3D2': (2231, 4231), 'word_C3BA': (2231, 4081), 'word_C3B0': (2531, 3931),
           'word_C5A4': (2431, 3331), 'word_C586': (3731, 8731)}[tag]
    A('| `%s` | %d … %d | %.1f … %.1f K | **%s … %s** | %s | %s |' % (
        tag, rng[0], rng[1], rng[0] / 10.0, rng[1] / 10.0,
        kelvin_c(rng[0]), kelvin_c(rng[1]), a[0], a[2]))
A('')
A('**Lecture** : −50…+150 °C pour le liquide de refroidissement, −50…+135 °C pour l’air d’admission,')
A('−20…+120 °C pour le gasoil, +100…+600 °C pour l’échappement. Ce sont **exactement les plages')
A('attendues** d’un moteur diesel, et elles **recoupent** les bornes annoncées par l’utilisateur')
A('(−40…+120 °C pour les axes de température). Le recoupement est un **contrôle indépendant** : la')
A('convention Kelvin × 10 n’a pas été choisie pour faire coïncider ces plages.')
A('')
A('### ⚠ Deux échelles de température coexistent — précision importante')
A('')
A('| famille de capteur | échelle | preuve |')
A('|---|---|---|')
A('| **CTN** (LDR, air, gasoil) | **Kelvin × 10** | 2731 = 0 °C et 3531 = 80 °C (utilisateur, vérifié) ; plages −50…+150 °C cohérentes |')
A('| **thermocouple d’échappement** | **°C × 10** | la valeur de repli de la 2ᵉ EGT vaut **6231**, soit **623,1 °C** — lue °C × 10, c’est la valeur par défaut attendue ; la même loi monte à **11731 = 1173,1 °C**, ce qui est un maximum d’échappement réaliste |')
A('')
A('**Les deux lectures ne peuvent pas être fusionnées** : en Kelvin × 10, la température LDR donnerait')
A('233 °C à −40 °C, ce qui est absurde ; en °C × 10, la même valeur serait correcte mais la plage')
A('−40…+120 °C des axes CTN deviendrait inatteignable. **Ce sont donc bien deux conventions distinctes,')
A('une par famille de capteur** — et c’est cohérent avec le fait que la loi d’une CTN produit')
A('naturellement des Kelvin alors qu’un thermocouple fournit des °C.')
A('')
A('`word_C586` (axes 3731…8731) et `word_C5A4` (2431…3331) restent **d’échelle non tranchée** : les deux')
A('lectures y sont données.')
A('')
A('### Les autres axes')
A('')
A('| variable | nom explicite | unité / échelle | confiance | note |')
A('|---|---|---|---|---|')
for tag, (n, u, c, note) in AXES.items():
    if 'K×10' in u:
        continue
    A('| `%s` | %s | %s | %s | %s |' % (tag, n, u, c, note))
A('')
