A('## 5 quinquies. ★ Les cartes sans axes, et les tables vérifiées à la main')
A('')
A('**Constat de l’utilisateur, confirmé par le binaire : il existe des cartes SANS AUCUN AXE.**')
A('Le gabarit `[tagY][nY][axeY][tagX][nX][axeX][grille]` n’est pas universel : certaines grilles sont')
A('stockées **nues**, leurs axes étant définis **ailleurs** (autre structure, ou axes fixes du')
