A('')
A('### ★ Le mécanisme qui explique « des axes partout dans le code »')
A('')
A('**Un handle peut viser l’intérieur d’une structure.** Vérifié sur la toute première courbe :')
A('')
A('```')
A('EA 0xE100A : [tag 0xC42E][n = 8][axe 8 mots : 200 … 4000][valeurs 8 mots]   -> 36 octets')
A('EA 0xE101E : = 0xE100A + 4 + 2x8  -> DÉBUT DES VALEURS, l’axe est sauté')
A('```')
A('')
A('Le handle `0x1400` pointe sur la structure entière ; le handle `0x1402` pointe **exactement sur')
A('les valeurs**. Un consommateur qui a déjà l’axe dans ses registres lit les valeurs sans relire')
A('l’axe ; un autre peut ne lire que les bornes. **Sur les 1 304 handles, 19 pointent ainsi sur des')
A('valeurs ou des grilles, et non sur un début de structure.**')
A('')
A('**⇒ C’est la réponse à ton observation** : ce ne sont pas des axes orphelins, ce sont des')
A('**adresses de sous-parties**. Le même bloc de calibration est découpé en plusieurs handles selon')
A('ce que chaque routine a besoin de lire.')
A('')
