A('| **Correction de démarrage** | `0xE80A0` | 2-D **8 × 10** : Y = régime (100…1000), X = T LDR (−25 … +100 °C). Grille **1300 … 12500**, décroissante avec la température, maximale à froid (12 500 vers 400-500 tr/min) | « carte de correction pour le démarrage (rôle exact ?) » | **Rôle précisé** : c’est un **enrichissement de démarrage à froid** — il vaut 3 à 10 fois plus à −25 °C qu’à +100 °C. L’**unité reste ouverte** (magnitude seule) |')
