A('')
A('> ⚠ **Statut : hypothèse forte, pas fait établi.** Rien dans le code visible ne nomme encore un')
A('> correcteur. Ce qui est établi, c’est que les triplets et les paires existent en grand nombre, et')
A('> que leur disposition est **régulière** — deux propriétés que des paramètres de régulation')
A('> expliqueraient bien.')
A('')
A('---')
A('')
A('## 6. Paramètres scalaires et blocs réservés')
A('')
A('**Blocs réservés** (`0xFFFE` + zéros, 32 octets) : **%d emplacements libres** dans le Datensatz —' % len(reserved))
A('le constructeur a prévu de la place pour des tables supplémentaires selon la variante.')
A('')
A('| ID | EA |')
A('|---|---|')
A(''.join('| `%04X` | `0x%05X` |\n' % (h, ea) for h, ea, _ in reserved))
A('**Sentinelles identifiées** :')
A('')
A('| sentinelle | position | sens proposé |')
A('|---|---|---|')
A('| `0xFFFE` | **premier mot** d’un bloc | **bloc sans variable** — emplacement non affecté |')
A('| `0xC300` | **fin** de chaque bloc réservé ; aussi `[word_1474+0x08]` et `[word_142A+0x22]` | **« pas de valeur » / case vide** |')
A('| `0xFF00` | avant `0xC300` dans les blocs réservés | second marqueur de fin |')
A('')
A('> **Conséquence** : la valeur `0xC300`, qui revenait à plusieurs endroits et que j’avais notée comme')
A('> « anomalie à instruire », est très probablement une **sentinelle d’absence de valeur** et non une')
A('> constante physique. Les champs qui la contiennent doivent être lus comme **vides**, pas comme')
A('> « −15 616 ».')
A('')
A('**Paramètres scalaires** (bloc de 2 octets) : %d. Le bloc ne contient qu’une valeur ; le premier mot' % len(scalar))
A('**est donc la valeur elle-même**, pas une adresse de variable.')
A('')
A('---')
A('')
A('## 6 bis. Les tables oubliées — recherche systématique')
A('')
A('**Question posée : reste-t-il des tables que l’on aurait manquées ?** Quatre vérifications')
A('indépendantes, reproductibles par `python3 outils/tables_oubliees.py`.')
A('')
A('### 1. Couverture : **97,9 %** des octets sont atteints par un handle')
A('')
A('Sur la fenêtre `0xE1000-0xEC000` (45 056 octets), **44 088 sont couverts** par une structure')
A('décodée. Il ne reste que **deux trous** :')
A('')
A('| trou | taille | contenu | lecture |')
A('|---|---|---|---|')
A('| `0xE1000-0xE100A` | 10 o | `0a 1d 0c 1d 0e 1d 10 1d 12 1d` | **cinq handles en clair** : `0x1D0A, 0x1D0C, 0x1D0E, 0x1D10, 0x1D12`. Petite **table de renvoi** placée juste avant la première structure. Les mêmes octets existent aussi à `0xE0FFA`. |')
A('| `0xEBC42-0xEC000` | 958 o | `9e 0d 53 0d 1b 09` puis remplissage `0xC3` | **fin du Datensatz** : 3 mots décroissants (3486, 3411, 2329) puis remplissage jusqu’à `0xEC000`. |')
A('')
A('**⇒ Conclusion nette : il n’existe pas de grande table hors pointeurs.** Le Datensatz est')
A('intégralement adressé. Les « oubliées » ne sont donc pas des octets perdus, mais des **structures')
A('dont on n’a pas décodé la disposition interne** — c’est l’objet des points suivants.')
A('')
A('### 2. Typologie des **1 056 blocs sans en-tête 1-D**')
A('')
A('C’est le vrai gisement : 1 056 blocs (27 854 octets) n’ont **aucun en-tête** au sens du gabarit')
A('`[variable][n][axe][valeurs]`. Voici ce qu’ils contiennent réellement :')
A('')
A('| type interne | blocs | octets | lecture |')
A('|---|---|---|---|')
for k, v, o, lec in TYPO:
    A('| %s | %d | %d | %s |' % (k, v, o, lec))
A('')
A('**Trois constats :**')
A('')
A('- **364 blocs de 6 octets = 3 mots** : c’est le gabarit le plus fréquent après les courbes. Ce sont')
A('  vraisemblablement des **triplets de paramètres liés** (seuil bas / seuil haut / temporisation),')
A('  cohérent avec les moniteurs décodés à l’étape 43 — **mais ce n’est pas prouvé bloc par bloc**.')
A('- **32 blocs sont des axes autonomes** (`[tag][n][n valeurs]`), dont **6 avec un tag inconnu** — les')
A('  vraies oubliées ici sont ces six tags.')
A('- **468 blocs restent non classés**, mais **24 230 octets seulement** : la médiane est de 2 octets.')
A('  L’essentiel de ce « non classé » est donc une masse de **scalaires isolés**, pas des tables.')
A('')
A('### 3. ★ 19 cartes 2-D **sans axes** — de vraies tables passées inaperçues')
A('')
A('Le décodeur exigeait le gabarit `[tagY][nY][axeY][tagX][nX][axeX][grille]`. Or **il existe des')
A('cartes stockées à plat, sans aucun axe** — elles étaient donc rejetées. La trame correcte se')
A('retrouve par **minimisation de la discontinuité** entre cellules voisines : sur les cartes déjà')
A('décodées, la méthode retrouve la bonne largeur **17 fois sur 25** (les échecs sont les grilles')
A('8×8, trop petites pour être discriminées).')
A('')
A('| EA | taille | mots | trame | lissage | plage | verdict |')
A('|---|---|---|---|---|---|---|')
for r in PLATES:
    A('| `%s` | %s o | %s | %s × %s | %s | %s … %s | **%s** |' % (
        r['EA'], r['taille'], r['mots'], r['nX'], r['nY'], r['lissage'], r['min'], r['max'], r['verdict']))
A('')
A('**Vérification visuelle** : `0xE5634` lu en 16×12 donne une surface parfaitement lisse et monotone')
A('(≈ 64 000 en haut à gauche, ≈ 60 000 en bas à droite, soit **−1 300 à −5 500 en complément à deux**) ;')
A('`0xEB792` lu en 16×16 monte de 45 à 510 avec des paliers francs. **Ce sont bien des cartes.**')
A('')
A('**Signal structurel fort** : ces blocs sont **contigus et régulièrement espacés** —')
A('`0xE5634, 0xE57B4, 0xE5934, 0xE5AB4, 0xE5C34, 0xE5DB4` sont **à 0x180 d’intervalle** (six cartes de')
A('384 o à la suite), et `0xEA558, 0xEA658, 0xEA758, 0xEAB60, 0xEAC60, 0xEAD60, 0xEAE60` **à 0x100**')
A('(sept cartes de 256 o). Un remplissage régulier de ce type ne se produit pas par hasard : c’est une')
A('**famille de cartes rangée par usage**, exactement comme l’étape 55 l’a montré pour les blocs')
A('adressés par handle.')
A('')
A('> ⚠ **Prudence sur quatre d’entre elles** : `0xE9D72`, `0xEA658`, `0xEAB60`, `0xEAC60` sont')
A('> **uniformes** (une seule valeur) — ce sont des **blocs remplis**, pas des cartes exploitables.')
A('> `0xE5DB4` et `0xE3BE4` ont une trame douteuse (lissage > 500) : **non retenues**.')
A('')
A('**⇒ Le décompte des cartes du catalogue passe de 66 à 66 + 19 = 85**, sous réserve de validation')
A('par le code consommateur.')
A('')
A('*Sorties : `etat_couverture.csv`, `typologie_blocs_sans_entete.csv`, `cartes_plates_sans_axes.csv`,')
A('`duplication_datensatz.csv`.*')
A('')
A('---')
A('')
