A('')
A('## 7 bis. ★★ La bibliothèque d’accès à la calibration — et les correcteurs')
A('')
A('**C’est l’avancée majeure : le code visible ne lit jamais la calibration directement. Il appelle')
A('une bibliothèque, et cette bibliothèque est dans la couche absente.** On ne connaît donc pas son')
A('corps — mais **ses sites d’appel, ses arguments et ses effets sont parfaitement lisibles.**')
A('')
A('### L’idiome de lecture')
A('')
A('```')
A('mov  r4, word_1474      ; r4 <- valeur du pointeur de la table 0xE1400')
A('mov  r5, [r4]           ; lecture dans la structure de calibration')
A('```')
A('')
A('Le handle `0x14xx` **est** l’offset de l’entrée de pointeur (`0xE0000 + h`), et la valeur lue est')
A('l’**offset de la structure** dans la même page. Un seul mécanisme, deux additions — d’où la')
A('simplicité du modèle et la régularité observée partout.')
A('')
A('### L’API de la couche absente')
A('')
A('| routine | appels | rôle établi | signature |')
A('|---|---|---|---|')
A('| **`unk_1D36`** | **168** | **interpolation 1-D** | `(r12 = handle, r13 = x)` → **r4 = y** |')
A('| **`unk_1D50`** | **72** | **interpolation 2-D** | `(r12 = handle, r13 = x, r14 = y)` → **r4** |')
A('| **`unk_1D6C`** | **44** | interpolation 1-D **avec destination mémoire** et **mémorisation de l’axe** | `(r12 = dest, r13 = x, r14 = handle)` → écrit dans `[r12]` |')
A('| **`unk_1D7E`** | **54** | même chose **sans nouvelle variable** : réutilise l’axe déjà chargé | `(r12 = dest, r13 = handle)` → **r4** |')
A('| **`word_1D94`** | **64** | interpolation entre **deux bases fournies par pointeurs** (cœur du calcul) | `(r12, r13 = bases, r14 = handle)` |')
A('| `word_1DA8` | 14 | non identifié | — |')
A('| **`word_1DDA`** | **35** | **pas de régulation** — voir ci-dessous | `(r12 = mode, r13 = état, r14 = cible)` → **r4 = nouvel état**, drapeau en `USR0` |')
A('')
A('**338 sites d’appel** au total, **203 courbes distinctes** réellement interpolées.')
A('')
A('### ★ Pourquoi des axes apparaissent « partout, sans carte »')
A('')
A('L’enchaînement est écrit noir sur blanc dans le code :')
A('')
A('```')
A('mov  r12, r0            ; r0 = pointeur de ZONE DE TRAVAIL')
A('mov  r13, word_C91C     ; x = régime')
A('mov  r14, word_1604     ; handle de la 1re courbe')
A('calls 0, unk_1D6C       ; l’axe est chargé et MÉMORISÉ dans [r0]')
A('mov  r12, r0')
A('mov  r13, word_1602     ; handle de la 2e courbe')
A('calls 0, unk_1D7E       ; réutilise l’axe déjà en place')
A('mov  r12, r0')
A('mov  r13, word_1600     ; handle de la 3e courbe')
A('calls 0, unk_1D7E       ; encore le même axe')
A('```')
A('')
A('**⇒ Une série de courbes partage un axe chargé une seule fois dans une zone de travail.** C’est')
A('la réponse complète au constat « des axes sans map » : ce ne sont ni des axes orphelins ni des')
A('cartes sans axes — ce sont des **axes mis en cache**, consommés par plusieurs courbes successives.')
A('Et cela **valide** l’existence des 19 grilles nues de la § 6 bis : leurs axes sont dans une zone')
A('de travail, pas à côté de la grille.')
A('')
A('### ★★ Les correcteurs : `word_1DDA` est le primitif de régulation')
A('')
A('Les **35 sites** d’appel suivent tous le **même patron**, sans exception dans l’échantillon :')
A('')
A('```')
A('mov  r12, <mode>            ; #0, #2710h (=10000), ou un registre')
A('mov  r13, word_X            ; r13 = VALEUR PRÉCÉDENTE (l’état persistant)')
A('mov  r14, <cible>           ; la consigne du pas courant')
A('calls 0, word_1DDA')
A('mov  word_X, r4             ; réécriture de l’état')
A('bmov word_FD00.n, USR0      ; USR0 remonte saturation / signe')
A('```')
A('')
A('**Un état persistant, une cible, un mode, un indicateur de saturation** : c’est la signature')
A('d’un **pas d’intégration / limiteur de pente / filtre du premier ordre**. Chaque boucle possède')
A('son propre mot d’état.')
A('')
A('### ★★★ Une chaîne de régulation complète, décodée (EA `0xAC65E`)')
A('')
A('```')
A('mov  r12, word_19D0         ; courbe de calibration')
A('mov  r13, [r0+#4]           ; entrée mesurée — SELECTIONNÉE PAR UN OCTET DE CALIBRATION')
A('calls 0, unk_1D36           ; r4 = CONSIGNE interpolée')
A('mov  MDL, #2710h            ; /10000  ->  échelle 0…100 %')
A('div  r8')
A('mov  r13, word_D836         ; état précédent')
A('mov  r14, r8               ; consigne du pas')
A('calls 0, word_1DDA          ; PAS DE RÉGULATION')
A('mov  word_D836, r4          ; nouvel état')
A('```')
A('')
A('Puis, immédiatement après, une **seconde courbe** `word_19C8` est interpolée **contre la même')
A('entrée** et son résultat publié en `word_D2EE`, l’état en `word_D2F0`.')
A('')
A('**⇒ C’est un canal de régulation complet : entrée → courbe → mise à l’échelle → pas de régulation')
A('→ sortie.** Et le choix de l’entrée est fait par `[word_141E + 0x23]`, **un octet de calibration** :')
A('c’est-à-dire que **la source de la boucle est elle-même calibrée**.')
A('')
A('### ★★ Un filtre à coefficient calibré (EA `0xACD4A`)')
A('')
A('```')
A('mov  r12, word_19F6         ; courbe de calibration')
A('mov  r13, word_C91C         ; x = RÉGIME')
A('calls 0, unk_1D36           ; r4 = coefficient K(régime)')
A('mov  r5, word_C940          ; valeur précédente')
A('add  r5, word_D854          ; + entrée')
A('add  r5, r4                 ; + K(régime)')
A('ashr r5, #1                 ; / 2')
A('mov  word_C940, r5          ; stockage')
A('```')
A('')
A('**`y[n] = ( y[n−1] + u[n] + K(régime) ) / 2`** : un **filtre récursif du premier ordre dont le')
A('coefficient est une courbe de calibration interpolée sur le régime.** C’est exactement « un')
A('traitement qui lit dans la zone de calibration » — et il est entièrement décodé.')
A('')
A('### Bilan de la chasse')
A('')
A('| question | réponse |')
A('|---|---|')
A('| le code lit-il la calibration ? | **oui, via 338 sites d’appel** à 4 interpolateurs |')
A('| combien de courbes sont réellement utilisées ? | **203** |')
A('| y a-t-il des correcteurs ? | **oui** : 35 boucles à état persistant via `word_1DDA` |')
A('| un PID complet est-il visible ? | **non** — le **pas** est dans la couche absente ; la **chaîne** qui l’entoure est décodée |')
A('| des valeurs en dur dans le code ? | **quasi aucune** : les gains sont des courbes, l’échelle est `#2710h`, et jusqu’au **choix de l’entrée** est un octet de calibration |')
A('')
A('**⇒ Ton hypothèse était la bonne** : le calculateur relit ses paramètres au lieu de les coder.')
A('Ce n’est plus une conjecture de méthode, c’est **observé sur 338 sites**.')
A('')
A('### Les grandeurs d’entrée les plus interpolées')
A('')
A('| variable | interpolations | lecture |')
A('|---|---|---|')
A('| **`word_C91C`** | **62** | **copie de travail du régime moteur** (120 axes, 0…6000) — variable indépendante dominante |')
A('| `word_C908` | 23 | température LDR (instantané diagnostic) |')
A('| `word_C940` | 13 | copie de `word_C60A` (0…1800) |')
A('| `word_C904` | 12 | air d’admission |')
A('| `word_C5A8` | 4 | masse d’air par tour |')
A('| `word_C68A` | 3 | non identifiée |')
A('')
A('---')
A('')
A('## 8. EEPROM — tout ce qui est établi')
A('')
A('### 8.1 Trois couches')
A('')
A('```')
A('applicatif  →  gestionnaire 0x94Axx-0x94Cxx  →  pilote sub_A0002  →  image 0xE5CE')
A('               redondance, rythme, options      page + offset          (RAM)')
A('```')
A('')
A('**Confinement prouvé** : les **74 occurrences** de la constante `0xE5CE` sont **toutes** situées entre')
A('les lignes **149820 et 152100**. **Aucune fonction applicative ne calcule jamais une adresse EEPROM.**')
A('⇒ tout champ EEPROM est atteignable par un handle du descripteur `0x0BA6`, donc présent dans')
A('l’inventaire des 1 304 handles.')
A('')
A('### 8.2 Le pilote `sub_A0002` (l. 149775)')
A('')
A('- `cmd > 0x29` rejeté ; descripteur de 12 octets à `0x0BA6` ; type 1 → `sub_A09E4`, type 4 → `sub_A0B72`')
A('- **handle = `[2 bits page][14 bits offset]`** ; page dans une table de 64 mots à `0x0FE00`')
A('- **adresse = `0xE5CE + offset`** ; codage : `[word_BBE+0xE5CE] & mask == 0` ⇒ `| 0x8000`')
A('- **20 appelants**, en 4 familles (§ 8.5)')
A('')
A('### 8.3 Le magasin interne `sub_95E78` (l. 128999-129403)')
A('')
A('| table | adresses RAM | pas | taille | nombre |')
A('|---|---|---|---|---|')
A('| **A** | `0xF819`, `0xF821`, `0xF829` | 8 | 8 octets | 3 |')
A('| **B** | `0xF831`, `0xF835`, `0xF839` | 4 | 4 octets | 3 |')
A('')
A('- sélection par **`byte_F842`** (0/1/2), table B autorisée par **`byte_F83C & 2`**')
A('- pointeur publié dans **`word_C18A`** ; le **premier octet de l’enregistrement sert de commande** `sub_A0002`')
A('- écriture **temporisée** : seuil **35** unités sur `word_F91C`, avec correction de rebouclage `−1`')
A('- **`byte_C8F5`** = drapeau d’activité du magasin')
A('')
A('### 8.4 Les quatre enregistrements de configuration persistante `0xF7ED…0xF815`')
A('')
A('| enreg. | tag | valeur | commande | bit de `byte_F80D` |')
A('|---|---|---|---|---|')
A('| n°1 | `0xF7ED` | 1 mot **×3** | `0x0C` | bit 0 |')
A('| n°2 | `0xF7F5` | 1 mot **×3** | `0x0C` | bit 1 |')
A('| n°3 | `0xF7FC` | 1 octet **×3** | `0x0D` | bit 2 |')
A('| n°4 | `0xF800` | 1 octet **×3** (compteur) | — | bit 7 |')
A('')
A('- **`byte_F80D`** = masque des éléments **en attente d’écriture** ; **`byte_F80E`** = élément courant ;')
A('  **`word_C186`** = pointeur sur le tampon ; **`word_C124`** = horodatage')
A('- les **20 écritures** de `byte_F80D` sont **toutes entre les lignes 127179 et 128305** : un seul sous-système')
A('- **seul effacement de bits d’option du code visible** : l. 127204-127222, `andb …, #9Fh` sur les **bits 5 et 6**')
A('  de l’enregistrement n°3, **dans les trois copies**, conditionné par la nullité du compteur `0xF800`')
A('- compteur `0xF800` décrémenté par **tranches de 62 500** (accumulateur 32 bits `word_F808/F80A`)')
A('')
A('### 8.5 Les 20 appelants de `sub_A0002`, en quatre familles')
A('')
A('| famille | sites | contenu persisté |')
A('|---|---|---|')
A('| **F1** configuration à triple redondance | l. 127438 (`0x0B`), 127491 (`0x0C`), 127544 (`0x0D`) | `0xF7F6`, `0xF7FD` — voir § 8.4 |')
A('| **F2** magasin `sub_95E78` | l. 129029-129092, 129904 | les 6 enregistrements |')
A('| **F3** quatre files de report | l. 152332, 152521, 152790, 152979 | `word_C462/464/466/468` → tampon `0xCFA4`, `byte_CF9D` |')
A('| **F4** commande calculée | l. 128443 (`word_C186`), 206384 (`MDH+0x10`) | seuls sites où la commande n’est pas un immédiat |')
A('')
A('**La couche absente a un nom** : `nullsub_8`, appelée **exactement 4 fois**, une par slot de F3.')
A('')
A('### 8.6 Les 13 groupes de l’image (étape 30)')
A('')
A('`word_C5A`, bloc 10 octets (`0xC895`), `word_BFA`, `word_D7A`, `word_D6E`+`word_D70`, `word_CF6`,')
A('`word_C1E`, `word_C4E`, `word_D26`, `word_D1A`, `word_D4A`, `word_CD2`, `word_CDE`, `word_BCA`.')
A('')
A('Écriture indirecte via `byte_C238` / `byte_C30D` / `byte_C31D`, recopiés par `sub_A0CCC`.')
A('**Aucun service de diagnostic n’appelle `sub_A0002` directement.**')
A('')
A('### 8.7 Validité de l’image : `byte_C2EC`')
A('')
A('| bit | sens | preuve |')
A('|---|---|---|')
A('| **0** | **image valide, utilisez-la** | `orb byte_C2EC,1` si **`word_CFAA == 0`** — l. 152021 |')
A('| **1** | **forcer les valeurs par défaut** | `byte_C2EC = 2` en `loc_90618` (l. 111754), quand `word_DE22 ∈ {0x28…0x2B}` |')
A('')
A('Cinq sites testent `byte_C2EC & 1` et **sautent l’initialisation par défaut** quand il est posé :')
A('l. **154442** (`word_C5BE/C5C0 = 0x7FFF`, `C5F4 = 0`), **160911** (`C5D2/C5D4/C5D6 = 0xFA`),')
A('**167312** (sept `word_C5xx` à 0), **213355** (`word_C3A6 = 0`), **210888** (`word_FD18.15`).')
A('')
A('`word_CFAA` n’est écrit qu’en **149916** (`= 0`) et **149922** : c’est **l’état de l’opération EEPROM**.')
A('')
A('### 8.8 Anti-falsification : un historique, pas un checksum')
A('')
A('**Sept algorithmes de checksum testés sans succès** (sommes mots/octets/quartets, CRC16 CCITT /')
A('XOTMODEM / IBM / ARC sur 3 plages) : **il n’y a pas de checksum à trouver** dans les 512 Ko.')
A('')
A('Ce qui protège réellement :')
A('')
A('```')
A('valeur courante word_C5B8 ──► persistée en EEPROM')
A('        │')
A('        ├──► historique 5 niveaux : C5D2, C5D4, C5D6, C5D8, C5DA  (PERSISTÉ)')
A('        │        └──► moyenne word_C5AE = somme / 5   (sub_97DDC)')
A('        │                 └──► comparée à [word_18F2+0x14] = 120')
A('        └──► comparée à [word_18F2+0x38] = 2')
A('             comparée à [word_1474+0x06] = 325  ──► décompte word_D6FE ──► byte_C317')
A('```')
A('')
A('**On ne peut pas falsifier la valeur sans falsifier simultanément son historique de 5 valeurs et sa')
A('moyenne — eux-mêmes persistés — ni sans franchir des seuils dont les valeurs sont dans le Datensatz,')
A('donc hors de l’EEPROM.**')
A('')
A('### 8.9 Le codage de variante — deux moitiés')
A('')
A('**Moitié EEPROM (étape 45)** : quatre enregistrements à tag, à valeur unique en triple copie,')
A('sélectionnés par le masque `byte_F80D`, écrits par la commande `0x0B`.')
A('')
A('**Moitié CAN (étape 50)** : `[word_18B2 + 0x12]` porte un **masque de variante, bits 2 à 7** ;')
A('chaque bit est **armé par un drapeau de trame CAN** et sélectionne un groupe de quatre valeurs')
A('`+0x14…+0x1A` du Datensatz.')
A('')
A('| bit de `[word_18B2+0x12]` | armé par |')
A('|---|---|')
A('| 2 | inconditionnel |')
A('| 3 | `word_FD38` |')
A('| 4 | `word_FD38+1` |')
A('| 5 | `word_FD7A` |')
A('| 6 | `word_FD7A+1` |')
A('| 7 | `word_FD7C` |')
A('')
A('```')
A('Lexia → code le BSI → trame CAN → word_FD38 / FD7A / FD7C')
A('                                    ↓')
A('                    [word_18B2+0x12] : quel bit est autorisé')
A('                                    ↓')
A('                    groupe de valeurs du Datensatz → word_C5A8, word_D1B2/BA/BE')
A('```')
A('')
A('> **Limite** : le lien entre ces drapeaux et **le régulateur, la clim, BVM/BVA** n’est **pas** établi.')
A('> La correspondance « bit ↔ option » est dans la **couche absente**. Un Datensatz ne contient que des')
A('> nombres et des axes, **pas des affectations d’options** — la seule voie restante est de comparer')
A('> deux EEPROM de véhicules de configurations connues.')
A('')
A('---')
A('')
A('## 9. Diagnostic : mémoire des défauts et moniteurs')
A('')
A('| objet | adresse | structure |')
A('|---|---|---|')
A('| table des défauts | `0xCAD0` | **96 × 4 octets** : `+0` drapeau, `+2` mot |')
A('| miroir | `0xFD21` | 96 octets |')
A('| codes transmis | `0xCCB2` | **96 mots** — code ET indice de descripteur (`mot+0x1C`) |')
A('| nb de défauts mémorisés | `byte_E466` | 0…7 |')
A('| enregistrements | `0xE467` | **7 × 22 octets** |')
A('| défaut courant | `0xE501` | `0xFF` = aucun |')
A('')
A('**Descripteur de défaut** : `mot(0xCCB2) + 0x1C`, **confirmé par trois sites indépendants**')
A('(l. 153103, 230034-230040, 231394). Champ : bits 0-1 = classe, bit 2 = drapeau, bits hauts = niveau.')
A('')
A('**Sélecteurs** : `0x8000` compter · `0x9000` effacer tout · `0xFF00` courant · `0x80xx` lire les 154')
A('octets · `0xEFxx` supprimer n° xx · `0xDFxx` lire n° xx · `0xD000` ajouter/mettre à jour.')
A('**Numéro 87 utilisé littéralement** (l. 152158).')
A('')
A('**Services** : `0x04` = ajout/mise à jour · `0x14` = compter + effacer · `0x17` = `sub_C1544`.')
A('')
A('**Cinq compteurs de défauts par niveau** : `0xC9F3…0xC9F7`, incrémentés une fois par défaut **présent**,')
A('sur une boucle de **96 entrées** (l. 231394), selon les bits hauts de `+0x1C`. Puis, si un compteur est')
A('non nul, le bit correspondant est posé dans **`word_C548`** (bits 0, 1, 2) ou **`word_C54A`**')
A('(bits 8, 15), d’après les numéros lus à `word_1818` = `02 01 00 08 0F`.')
A('')
A('**Deux types de moniteurs** : `word_CFD4` bit 0 = **durée**, bit 7 = **valeur**.')
A('Confirmation `sub_A1E9E` : `and CFD4,r12` → inhibitions `byte_CFC2/CFC3` → décompte `byte_CFC4` →')
A('`or word_CFD6, r12`. Inhibitions actives : `byte_C2F5`, `byte_CFDC`, `word_C0BC` ; inhibition globale')
A('par **`word_FD2E`**. **Power latch** : `word_FD0C.15` **gèle l’évaluation** (l. 153175).')
A('')
A('**Anti-rebond à hystérésis** (étape 49) : deux courbes 1-D (`word_18AA`, `word_18AC`) sur une même')
A('entrée donnent les **deux bornes d’une fenêtre** ; le résultat est comparé à une référence ; le')
A('changement d’état exige **N cycles consécutifs** (`word_1474+offset`). Sept compteurs `word_D6EE…D6FA`.')
A('')
A('---')
A('')
A('## 10. Registre des erratas et des hypothèses retirées')
A('')
A('*Conservé volontairement : ces pistes ne doivent pas être réintroduites.*')
A('')
A('| # | hypothèse retirée | raison |')
A('|---|---|---|')
A('| 38 §1 | ~~« la banque F est une copie de E »~~ → **RÉHABILITÉE (étape 57)** | l’argument de retrait était faux : **14 octets d’écart est exactement la signature d’une copie variante**, pas d’une zone distincte. Comparaison octet par octet : 49 138 octets identiques, 14 différents. **F est bien une copie de E.** |')
A('| 39 §2 | checksum de bloc | **invérifiable depuis le code visible** ; 7 algorithmes échouent |')
A('| 39 §3 | piste par les usages de `unk_7EC8` | **un seul appelant**, corps absent |')
A('| 43 §4 | les 5 entrées = les 5 identifiants EEPROM | le magasin compte **6** enregistrements |')
A('| 46 §4 | format de descripteur partagé (« seuil à +6 ») | `+6` est un **indice**, pas un champ typé |')
A('| 47 §1 | les blocs sont des **structures** | ce sont des **suites de mots indexés** |')
A('| 47 §3 | 250 = Vmax (240 ou 250 ?) | **250 est une durée** de confirmation, en cycles |')
A('| 47 §4 | `word_C5B8` = grandeur physique | c’est **un compteur** |')
A('| 48 §5 | `word_1474` = blocs de **seuils** | ce sont des **durées** (étape 49) |')
A('| 48/49 | « pointeur manquant » sur `word_1952` | le code lit jusqu’à `+0x3C` : les 62 octets sont **utilisés** |')
A('| 49 | `word_18F6` = enregistrement triple | répétition **interrompue** et non monotone |')
A('| **56** | `word_C3D2`, `word_C3BA`, `word_C3B0` = **masse d’air par tour (mg ×10)** | inféré de la **seule plage** 2 200-4 300 ; la chaîne capteur de l’étape 13 prouve que ce sont des **températures**. **ERREUR DE MÉTHODE : une plage ne prouve rien.** |')
A('| **57** | « il n’y a pas de somme de contrôle » | les **champs** sont localisés (`0xE0FF6`, `0xE0FFC`, `0xEBCFC`) ; c’est le **calcul** qui reste inconnu. |')
A('| **57** | « 66 cartes 2-D » = total | **sous-décompte** : 19 cartes stockées **à plat, sans axes**, échappaient au décodeur, et 6 cartes à en-tête masquées par le test 1-D. **Total : 72 + 19 = 91 cartes.** |')
