A('## 12. Annexe A — Correcteurs, filtres et boucles de régulation')
A('')
A('*Consigné ici, en fin de document, tout ce qui a été identifié comme **traitement** et non comme')
A('donnée : les correcteurs, les filtres, et les courbes qui les alimentent.*')
A('')
A('### A.1 — Les quatre interpolateurs (bibliothèque de la couche absente)')
A('')
A('| routine | appels | rôle |')
A('|---|---|---|')
A('| `unk_1D36` | 168 | interpolation **1-D** : `(handle, x)` → `r4` |')
A('| `unk_1D50` | 72 | interpolation **2-D** : `(handle, x, y)` → `r4` |')
A('| `unk_1D6C` | 44 | 1-D **avec destination mémoire** et **mémorisation de l’axe** : `(dest, x, handle)` |')
A('| `unk_1D7E` | 54 | idem **sans nouvelle variable** — réutilise l’axe en cache : `(dest, handle)` → `r4` |')
A('')
A('**338 sites d’appel · 203 courbes distinctes réellement interpolées · 62 sur le régime seul.**')
A('')
A('### A.2 — Les deux traitements entièrement décodés')
A('')
A('**Filtre récursif à coefficient calibré** — EA `0xACD4A` :')
A('')
A('```')
A('K = unk_1D36(handle 0x19F6, x = régime)        ; le coefficient EST une courbe')
A('y[n] = ( y[n-1] + u[n] + K ) / 2               ; ashr #1')
A('```')
A('')
A('**Canal de régulation complet** — EA `0xAC65E` :')
A('')
A('```')
A('consigne = unk_1D36(handle 0x19D0, x = entrée)  ; consigne CALIBRÉE')
A('consigne = consigne / 10000                     ; #2710h  ->  échelle 0…100 %')
A('état = word_1DDA(mode, état précédent, consigne) ; LE PAS DE RÉGULATION')
A('word_D836 = état')
A('puis  unk_1D36(handle 0x19C8, même x) -> word_D2EE  ; seconde grandeur calibrée')
A('```')
A('')
A('**Et la source de la boucle est elle-même calibrée** : l’entrée est choisie entre `C616`, `C91C`')
A('et `C93E` par l’octet `[0xE1148 + 0x23]`.')
A('')
A('### A.3 — Le primitif de régulation `word_1DDA` : **%d boucles**' % len(BOUCLES))
A('')
A('Signature constante : `(r12 = mode, r13 = état précédent, r14 = cible) → r4 = nouvel état`.')
A('Un état persistant par boucle, plus un indicateur de saturation remonté en `USR0`.')
A('')
A('| fonction | ligne | état persistant | cible |')
A('|---|---|---|---|')
for _b in BOUCLES:
    _o = dict(kv.split('=', 1) for kv in _b['cibles'].split(' ') if '=' in kv) if _b['cibles'] else {}
    A('| `%s` | %s | `%s` | `%s` |' % (_b['fonction'], _b['ligne'], _o.get('etat', '?'), _o.get('cible', '?')))
A('')
A('**Lecture** : `sub_A7D96` porte à lui seul douze boucles indépendantes (`D810`, `D812`, `D814`,')
A('`D816`, `D818`, `D81A`, `D81C`, `D81E`, `C5DC`, `C5DE`, `C5E0`, `D7AE`) — c’est le **cœur de')
A('régulation** du calculateur, et il est aussi l’un des plus gros consommateurs de calibration.')
A('')
A('---')
A('')
A('## 13. Annexe B — Les switchs de calibration : **%d options**' % len(SW_REELS))
A('')
A('**Un switch se reconnaît à trois traits simultanés** — il n’y a pas d’ambiguïté :')
A('')
A('```')
A('mov   r5, word_141E        ; handle de calibration  ->  structure EA 0xE1148')
A('movb  rl4, [r5+#0Dh]       ; OCTET d’option, offset 13')
A('jmpa  cc_NZ, loc_A4916     ; si NON NUL  ->  SAUTE 864 LIGNES ENTIÈRES')
A('```')
A('')
A('**Les paramètres numériques sont des MOTS ; les switchs sont des OCTETS.** C’est le discriminant')
A('qui les sépare sans erreur. Et le saut est presque toujours un **saut long (`jmpa`)**, c’est-à-dire')
A('un **shunt de bloc entier** — pas un ajustement, une décision.')
A('')
A('| mesure | valeur |')
A('|---|---|')
A('| switchs conditionnels | **%d** |' % len(SW_REELS))
A('| fonctions concernées | **%d** |' % len(set(x['fonction'] for x in SW_REELS)))
A('| structures de calibration porteuses d’options | **%d** |' % len(STRUCTS))
A('| lignes de code shuntées au total | **%d** |' % sum(int(x['bloc_shunte']) for x in SW_REELS))
A('| actifs si l’octet est NUL | %d |' % sum(1 for x in SW_REELS if x['polarite'] == 'actif si NUL'))
A('| actifs si l’octet est NON NUL | %d |' % sum(1 for x in SW_REELS if x['polarite'] == 'actif si NON NUL'))
A('')
A('*(%d sites supplémentaires ont été écartés : le saut qui les suit est inconditionnel, ce ne sont donc pas des switchs.)*' % (len(SW) - len(SW_REELS)))
A('')
A('### B.1 — Les structures d’options, par nombre d’options')
A('')
A('| handle | EA | options | lignes shuntées | remarque |')
A('|---|---|---|---|---|')
for _h, _lst in STRUCTS[:12]:
    _ea = _lst[0]['structure']
    _tot = sum(int(x['bloc_shunte']) for x in _lst)
    _rem = ''
    if _h == '0x141E':
        _rem = '**le bloc d’options maître** — présent dans 7 fonctions différentes'
    elif _h == '0x18B2':
        _rem = 'déjà identifié comme **sélecteur de variante** (offsets 18 = 0x12 et 28 = 0x1C) — recoupement indépendant'
    elif _h == '0x1928':
        _rem = 'options par paires d’offsets (0/1, 10/11, 16/17…) : un octet par stratégie'
    elif _h == '0x1972':
        _rem = 'options groupées par paires (22/23, 34/35, 36/37, 38/39, 44/45, 50/51)'
    A('| `%s` | `%s` | %d | %d | %s |' % (_h, _ea, len(_lst), _tot, _rem))
A('')
A('### B.2 — Les vingt switchs qui shuntent le plus de code')
A('')
A('| fonction | structure | offset | valeur ici | polarité | lignes shuntées |')
A('|---|---|---|---|---|---|')
for _x in SW_REELS[:20]:
    A('| `%s` | `%s` | +%s | `%s` | %s | **%s** |' % (
        _x['fonction'], _x['structure'], _x['offset'], _x['valeur'],
        _x['polarite'], _x['bloc_shunte']))
A('')
A('**Trois exemples parlants :**')
A('')
A('- `sub_A1E9E` lit `[0xE1148 + 13]` ; l’octet vaut **0** et la condition est « actif si NON NUL » :')
A('  **les 864 lignes sont exécutées** dans cette calibration.')
A('- `sub_A5C92` lit `[0xE1148 + 12]` ; l’octet vaut **0** et la condition est « actif si NUL » :')
A('  **les 787 lignes sont shuntées** — une stratégie entière est désactivée.')
A('- `sub_AFAA0` lit `[0xE232A + 0]` ; l’octet vaut **1**, condition « actif si NON NUL » :')
A('  **578 lignes sont actives**. Cette même structure porte **7 options** lues depuis 4 fonctions.')
A('')
A('**⇒ C’est exactement le mécanisme que tu décrivais** : un octet de calibration qui autorise ou')
A('interdit une portion entière de fonction, sans rien changer au code. **Modifier cet octet change')
A('la stratégie appliquée**, et les blocs shuntés sont assez gros (jusqu’à 864 lignes) pour contenir')
A('des algorithmes complets, pas des cas particuliers.')
A('')
A('### B.3 — ★ Trier : tous les octets ne sont pas des switchs')
A('')
A('**Correction importante.** Une lecture d’octet en calibration ne suffit pas à faire un switch.')
A('Sur **%d** lectures d’octets examinées :' % len(SWC))
A('')
A('| classe | nombre | critère |')
A('|---|---|---|')
A('| **SWITCH** | **%d** | l’octet est immédiatement testé par un saut conditionnel |' % len(SW_SW))
A('| **DONNÉE** | **%d** | l’octet est utilisé par un calcul (`movbz`, `and`, `add`, `mul`) — **c’est une valeur, pas un interrupteur** |' % len(SW_DO))
A('')
A('**%d %% des lectures d’octets sont des données, pas des switchs.** Exemple net : les octets de' % round(100 * len(SW_DO) / max(1, len(SWC))))
A('`0xE5FE8` (handle `0x1928`, 37 octets) sont lus puis combinés arithmétiquement — **ce sont des')
A('coefficients, pas des options**. Un outil qui se contenterait de voir « octet de calibration +')
A('saut dans les environs » les classerait à tort comme switchs.')
A('')
A('### B.4 — ★★ Le patron réel : `SWITCH` à 2 états, `MODE` à N stratégies')
A('')
A('La forme à **deux** états est un vrai interrupteur. Mais la forme la plus fréquente est un')
A('**sélecteur**, et il faut la lire en cascade. Exemple intégral, option `[0xE6542 + 0x16]` :')
A('')
A('```')
A('mov  r5, word_1972')
A('movb rl4, [r5+#16h]        ; octet d’option  = %s dans ce firmware' % '0x01')
A('jmpr cc_Z, loc_AA736       ; 0  ->  bclr word_FD0E.3          TOUJOURS INACTIF')
A('cmpb rl4, #1')
A('jmpr cc_Z, loc_AA73A       ; 1  ->  piloté par le drapeau CAN word_FD7C.8')
A('cmpb rl4, #2')
A('jmpr cc_Z, loc_AA746       ; 2  ->  piloté par le SEUIL calibré [0xE6542+0x12]')
A('jmpr cc_UC, loc_AA75C      ; autre -> 4e stratégie')
A('```')
A('')
A('**C’est exactement « soit ignoré, soit une autre stratégie »** — et ici les stratégies sont :')
A('**désactivé · par le CAN · par un seuil de calibration · autre**. L’octet ne dit pas oui/non,')
A('il dit **qui décide**.')
A('')
A('Les options de `0xE6542` vont d’ailleurs **par paires** d’offsets — (16/17), (22/23), (28/29),')
A('(34/35), (44/45), (50/51) — ce qui suggère **un octet « stratégie » + un octet « état »** par')
A('fonction, et chaque paire ne shunte que **8 lignes** : c’est une **substitution**, pas un bloc.')
A('')
A('### B.5 — Ce que contiennent les blocs shuntés')
A('')
A('| fonction | structure | +off | valeur | bloc | interpolations | axes appelés |')
A('|---|---|---|---|---|---|---|')
for _x in sorted(SW_SW, key=lambda r: -int(r['taille_bloc']))[:12]:
    A('| `%s` | `%s` | +%s | `%s` | **%s** | %s | %s |' % (
        _x['fonction'], _x['structure'], _x['offset'], _x['valeur'],
        _x['taille_bloc'], _x['interpolations'], _x['axes'] or '—'))
A('')
A('**Le plus gros** (`[0xE1148+13]`, 864 lignes) contient **5 interpolations** : courbes sur `C588`,')
A('`C5A4`, `D1FE`, et deux **cartes** — `D1E6 × D1F6` et `D202 × C590`. C’est donc **tout un étage de')
A('calcul**, pas un cas particulier.')
A('')
A('### B.6 — Deux réserves de méthode, à conserver')
A('')
A('1. **L’attribution des fonctions n’est pas fiable partout.** Le désassembleur laisse des zones de')
A('   code **sans étiquette**. Les plus gros switchs (`864`, `787`, `578`, `387` lignes) sont dans du')
A('   **code non nommé** : les rattacher à `sub_AFAA0` — qui ne fait que **10 lignes** — aurait été')
A('   faux. Le catalogue les marque `(code non nommé)`.')
A('2. **La polarité doit se lire, pas se supposer.** « actif si NUL » prêtait à confusion : il faut')
A('   dire **« le saut est pris si l’octet est NUL »**, donc le bloc est **exécuté** quand l’octet est')
A('   non nul. Une inversion de lecture inverse la conclusion.')
A('')
A('### B.7 — ★ L’EGR : ce qui est établi, et ce qui ne l’est pas')
A('')
A('**Établi — la famille de cartes et son usage :**')
A('')
A('| handle | EA | contenu |')
A('|---|---|---|')
A('| `0x1B3C` | `0xE83DA` | bloc de paramètres de la zone air (octets lus 9 fois dans un même calcul) |')
A('| `0x1B3E` | `0xE83F4` | courbe sur le **régime**, 19 points, 0…5200 → 0…7430 |')
A('| **`0x1B40`** | **`0xE8444`** | **CARTE 16 × 16 : régime 0…5200 × air mesuré 300…1150 mg → 0…7600** |')
A('| `0x1B44` | `0xE86F4` | carte préchauffage (régime × T LDR) |')
A('| `0x1B4C` | `0xE8872` | seconde carte régime × air, **grille nulle** (emplacement vacant) |')
A('')
A('**Ces handles sont interpolés à quelques lignes d’une lecture de la masse d’air mesurée**')
A('(`word_C5A8` / `word_C3E6`) — c’est le schéma d’une **limitation par la masse d’air**, dont la')
A('carte `0xE8444` est l’élément central.')
A('')
A('**Candidats switchs de cette zone :**')
A('')
A('| site | structure + off | valeur | effet |')
A('|---|---|---|---|')
A('| `l.181491` | `0xE83DA + 17` | `0x01` | saute 387 lignes **si NUL** → **bloc exécuté** |')
A('| `l.178313` | `0xE7FF8 + 0` | `0x01` | bloc de 6 lignes |')
A('| `l.167740` & suivants | `0xE6542` paires | 0/1/2 | **sélecteurs de stratégie** (voir B.4) |')
A('')
A('**Ce que je dois écarter, et pourquoi.** Le bloc gaté par `[0xE83DA+17]` (387 lignes) contient une')
A('**division avec reste** — `divu` puis lecture de `MDH` comparé à `word_D91E`, sur un compteur')
A('`word_D920` incrémenté — c’est un **processus périodique / base de temps**, pas une fonction')
A('spécifique. **Je ne le retiens donc pas comme switch EGR.**')
A('')
A('**Conclusion honnête : la région EGR est identifiée, le switch EGR ne l’est pas encore.**')
A('Ce qui manque est un lien fonctionnel : savoir quel mot RAM porte la **consigne de l’électrovanne EGR**.')
A('Tant que ce mot n’est pas nommé, tout octet de cette zone peut aussi bien commander la')
A('suralimentation, la vanne EGR ou le volet d’admission. **Le prochain pas est donc d’identifier la')
A('sortie, pas l’entrée.**')
A('')
A('### B.8 — Le bloc d’options `0xE111E` (42 octets) : qui le lit, ce qu’il fait, la zone touchée')
A('')
A('**Résolution de l’adresse.** L’octet `0x6111F` est l’octet `+1` du bloc ; la base du Datensatz est au')
A('fichier `0x60000`, donc `EA = 0x6111E − 0x60000 + 0xE1000 + 0xFF000`… plus simplement :')
A('**fichier `0x6111E` ⇔ EA `0xE111E`**. Le pointeur est l’entrée n° 14 de la table de pointeurs')
A('(fichier `0x61400`, EA `0xE1400`) : `EA 0xE141C = 0x111E` ; c’est le handle **`0x141C`**, symbole RAM')
A('`word_141C`, qui vaut donc `0x111E`.')
A('')
A('**Bornes du bloc — preuve arithmétique.** Pointeur suivant `word_141E = 0x1148` (EA `0xE1148`).')
A('`0xE111E + 42 = 0xE1148` : le bloc fait **exactement 42 octets**.')
A('**Correction** : le bloc voisin `0xE1148` ne fait pas 60 octets mais **52** (`0xE1148 → 0xE117C`,')
A('pointeur `word_1420 = 0x117C`). Le « 60 » de l’étape 60 était un décompte de sites, pas une taille.')
A('')
A('**Nature : ce n’est pas une carte.** Aucun tag, aucun `n`, aucune valeur d’axe : c’est un **bloc de')
A('paramètres**, au sens de la règle « une map sans en-tête n’a pas d’axes ». 42 octets, presque tous')
A('à `0x00`/`0x01`, sauf `+0x0A = 0x30`, `+0x0E = 0x08`, `+0x16 = 0x0A`, `+0x17 = 0x02`,')
A('`+0x18 = 0x02`, `+0x19 = 0x03`, `+0x1A = 0x02`, `+0x27 = 0x01`, `+0x28 = 0x02`.')
A('')
A('**35 octets sur 42 sont lus**, chacun par **un seul type de lecteur** :')
A('')
A('| usage | offsets | mécanisme |')
A('|---|---|---|')
A('| **recopie en RAM** (31 octets) | `+1 +2 +3 +4 +6 +8 +9 +0x0A +0x0E +0x0F +0x10 +0x15…+0x1F +0x20…+0x28` | 3 routines copient l’octet dans une variable `byte_C2Bx`/`byte_C2Cx` |')
A('| **test direct** (5 octets) | `+0x0B` (2 sites), `+0x0C`, `+0x0D`, `+0x11` | le saut est immédiatement pris selon la valeur |')
A('')
A('**Les 9 lecteurs de `word_141C`** (aucun autre site dans tout le listing) :')
A('')
A('| site | fonction réelle | ce qui est fait |')
A('|---|---|---|')
A('| `l.151755` `loc_A11BA` | bloc non nommé (seg014) | recopie **10 octets** → `C2B1 C2B2 C2B0 C2C5 C2C9 C2B3 C2B9 C2BB C2B4 C2BA` |')
A('| `l.199982` `loc_BD7D6` | `sub_BD464` | recopie **20 octets** → `C2BF C2CC C2C7 C2B8 C2C3 C2B7 C2C0 C2D0 C2D1 C2CE C2CF C2CB C2CD C2C8 C2BE C2C6 C2CA C2BD C2C4 C2C1` |')
A('| `l.200395` | bloc non nommé (seg015) | recopie `+0x10` → `C2B6` ; puis **teste `+0x11`** |')
A('| `l.196409` | bloc non nommé (seg015) | teste `+0x0B` **deux fois** |')
A('| `l.196438` | bloc non nommé (seg015) | teste `+0x0C` |')
A('| `l.196446` | bloc non nommé (seg015) | teste `+0x0D` contre `1` |')
A('')
A('**Consommation des miroirs : ≈ 341 références** dans le code pour ces 31 octets. L’octet `+0x27`')
A('(→ `byte_C2BA`) est le plus utilisé : **63 références**.')
A('')
A('#### Ce que font les octets testés directement')
A('')
A('| octet | valeur | effet exact |')
A('|---|---|---|')
A('| `+0x0B` | `0x00` | si **non nul** : `word_DB64 = 0` **et** `word_DB66 = 0` — la consigne est annulée. Si nul : consigne = interpolation de `[word_14A0 + 0x32]`, **ou** constante calibrée `word_C506` si les bits `0x800`/`0x200` de `[word_1468]` le demandent |')
A('| `+0x0C` | `0x00` | si **non nul** : la consigne passe par **`unk_2020`** (régulateur, voir B.9) ; si nul : par **`unk_1FE8`**. **L’octet choisit la structure du régulateur** |')
A('| `+0x0D` | `0x01` | `cmpb #1` → `byte_DB73 = 5`, sinon `4`. C’est un **code d’état** d’une machine à états |')
A('| `+0x10` | `0x01` | recopié dans `byte_C2B6` |')
A('| `+0x11` | `0x00` | **verrou à mémoire** : `C8EB := C2B6` ; si `C2B6 + C2B5 == 1`, alors si `+0x11 == 1` → `C8EB = 1, C2B5 = 0`, sinon → `C8EB = 0, C2B5 = 1` |')
A('')
A('#### ★ La zone que ce bloc touche')
A('')
A('Aucun lecteur n’est dans le segment d’injection : les recopies sont en **seg014** (CAN/diagnostic) et')
A('**seg015** (supervision). En revanche les miroirs `byte_C2B0…byte_C2D1` sont lus **partout**. Le bloc')
A('commande donc trois étages :')
A('')
A('1. **La machine à états de supervision** — `byte_DB73`, **14 états** (`0…0x0D`) sélectionnés par une')
A('   **table de saut à EA `0xE0AE6`** (`movbz r4, byte_DB73 ; shl #1 ; add #0AE6h ; mov r4,[r4] ; jmpi`).')
A('   Les 14 cibles sont `0xAEE0 0xAFB0 0xB03C 0xB0D4 0xB16A 0xB134 0xB1E2 0xB22C 0xB25C 0xB27E')
A('   0xB1A2 0xB08C 0xB2D6 0xB3D8` (offsets dans le segment 015).')
A('2. **La consigne d’air et sa régulation** — `word_DB66` (consigne) / `word_DB64` → `word_D4B0` /')
A('   `word_D4B2`, puis régulateur `unk_2020` ou `unk_1FE8`, puis `unk_1EBC`, avec **saturation')
A('   `0x7FFF`/`0x8000`** et **butées anti-emballement** `[r7]` / `[r7+2]`.')
A('3. **Le diagnostic** — `+0x0E = 0x08`, bit 0 actif : enregistre **deux identifiants** via')
A('   `sub_9CF70` (`9 / 0x349`) et (`0x0D / 0x389`).')
A('')
A('#### ★★ Découverte de structure : `0xE0000–0xE1000` n’est pas de la calibration')
A('')
A('Les tables de saut de la couche code vivent dans le **début du Datensatz**. Sept bases recensées :')
A('`0xE0966`, `0xE0970`, `0xE098E`, `0xE09C6`, `0xE09DC`, `0xE0A62`, `0xE0AE6`. Le motif est toujours')
A('`movbz rN, rlN ; shl rN, #1 ; add rN, #0XXXh ; mov rN, [rN] ; jmpi cc_UC, [rN]`.')
A('Les entrées sont des **offsets 16 bits de segment** (ex. `0xE0966` → `0x95C6`, `0x95E0`, `0x965A`,')
A('`0x96A4`, `0x96EE`, …). **Conséquence** : la couverture `0xE1000–0xEC000` ne décrit que la')
A('calibration ; la zone `0xE0000–0xE1000` est du **code adressé par table**, à inventorier à part.')
A('')
A('#### ★ Nouvelle famille « couche absente » (corps `ds 1`)')
A('')
A('| routine | appels | rôle observé |')
A('|---|---|---|')
A('| **`unk_2020`** | **2** (`l.173370`, `l.196462`) | reçoit **6 arguments**, dont deux pointeurs de structure de calibration et un pointeur de sortie ; renvoie la correction. **Cœur du régulateur PI** |')
A('| `unk_1FE8` | **8** | même famille, variante de régulateur (cf. `+0x0C`) |')
A('| `unk_1EBC` | **2** | appelé juste après, sur les mots `DB6A/DB6C/DB6E` — étage de lissage/limitation |')
A('| `word_1DA8` | **14** | pointeur de routine appelé avec `r12` = sortie, `r13 = #2710h` (échelle ×10000) |')
A('')
A('---')
A('')
A('### B.9 — ★ CONFIRMÉ : l’octet `0xE111E+0x0B` neutralise la boucle d’air/EGR')
A('')
A('**Ce que fait exactement l’octet** (valeur `0x00` dans ce firmware), aux **trois** endroits où il est testé :')
A('')
A('| site | code | effet |')
A('|---|---|---|')
A('| `l.196410` | `jmpr cc_NZ, loc_BB548` | `word_DB64 = 0` **et** `word_DB66 = 0` — la **consigne est annulée** |')
A('| `l.196439` | `jmpr cc_NZ, loc_BB566` | force `r5 = 0` puis `mov [r0], r5` ⇒ la valeur interpolée stockée dans `word_D492` est **zéro** |')
A('| `loc_BB550` | (branche atteinte) | `word_DB6C = 0` et `word_DB6E = 0` — le **terme accumulé est effacé** |')
A('')
A('**Donc oui : l’octet coupe la boucle fermée.** Consigne à zéro + intégrale à zéro = le régulateur ne')
A('peut plus rien produire. Ce n’est pas un « switch EGR » qui débranche une fonction nommée : c’est un')
A('**interrupteur de boucle** qui met toutes les entrées du régulateur à zéro. **La formulation est validée.')
A('')
A('#### La boucle, étage par étage')
A('')
A('| # | étage | code / donnée |')
A('|---|---|---|')
A('| 1 | **consigne** | carte **8 × 8** `word_1C98` → **EA `0xE9660`**, appelée `l.196401` `unk_1D50(handle, word_C91C, r8)` |')
A('| 2 | **repli consigne** | constante calibrée `word_C506` si les bits `0x800`/`0x200` de `[word_1468]` le demandent (`l.196419`) |')
A('| 3 | **correction neutre** | courbe `word_1C90` → **EA `0xE9626`**, n=2, axe tag `0xC7C6` 1000…3000 — **les deux valeurs sont `0`** |')
A('| 4 | **régulateur PI** | `unk_2020` (2 appels) puis `unk_1EBC`, avec **saturation `0x7FFF`/`0x8000`** et butées `[r7]`/`[r7+2]` |')
A('| 5 | **hystérésis / anti-rebond** | `sub_BAC40` : état `[r13]` 0…`0xFF`, compare `r12`, retourne 0 ou 1 avec drapeaux `DB84`/`DB86` |')
A('| 6 | **moniteur de dérive** | `l.197160` : `r4 = word_DB68 + word_DB66`, comparé à `[word_14A0+0x5C]`, seconde condition `[word_14A0+0x4C] ≥ word_DB52` ⇒ compteur `word_DB5E` **saturé à `0x7FFF`** |')
A('')
A('#### ★★ La carte de consigne, décodée octet par octet : `0xE9660`')
A('')
A('| champ | valeur | lecture |')
A('|---|---|---|')
A('| tag Y | **`0xC42E`** | **régime moteur** |')
A('| n Y | `8` | axe : `200, 500, 750, 1000, 1500, 2000, 3000, 4000` |')
A('| tag X | **`0xC7B8`** | grandeur **dérivée** (pas un capteur brut : `word_C7B8` est recalculé `l.190859` après un **max-glissant** `word_DBB8`) |')
A('| n X | `8` | axe : `2000, 3000, 5000, 7000, 9000, 10000, 11000, 13000` |')
A('| grille | `8 × 8` | 64 valeurs |')
A('')
A('Une consigne bâtie sur une **carte (régime × grandeur 2 000…13 000)** n’est pas une consigne de')
A('carburant (le débit de carburant se calcule, il ne se lit pas sur une carte 8 × 8 de cette forme) :')
A('c’est **une boucle d’air**. C’est le point qui rend l’hypothèse EGR cohérente.')
A('')
A('#### Ce qui reste à trancher — le seul doute qui subsiste')
A('')
A('**`word_C7B8` : air (×10, donc 200…1300 mg) ou pression (mbar) ?** Les deux donnent la même plage')
A('2000…13000. Tant que ce mot n’est pas nommé, on ne peut pas séparer **EGR** de **suralimentation')
A('(VNT)** — les deux se règlent en boucle fermée sur une carte régime × air/pression.')
A('')
A('Le test qui tranche : remonter `word_C7B8` jusqu’à sa source capteur (loi ADC ou `word_C3E6`).')
A('S’il descend du débitmètre ⇒ **c’est l’EGR**.')
A('')
A('#### Les sorties de la boucle ne pilotent rien directement')
A('')
A('`word_D48E`, `word_D49C`, `word_D4A4`, `word_D49E`, `word_D4A8`, `word_D4AE`, `word_D4B0`, `word_D4B2`')
A('sont **écrits et jamais relus** dans tout le listing : ce sont des **images de mesure** (bloc diagnostic /')
A('CAN), pas des commandes. La grandeur qui sort réellement de la boucle est `word_DB6A` / `word_DB6E`,')
A('consommée **uniquement** par la couche absente (`unk_2020`, `unk_1EBC`).')
A('**Conclusion** : la boucle est neutralisée par `+0x0B`, mais **l’actionneur physique n’est pas encore')
A('nommé** — le prochain pas reste la sortie PWM.')
A('')
A('---')
A('')
A('### B.10 — Portée mesurée de chaque octet du bloc `0xE111E` : ils n’agissent PAS sur les mêmes fonctions')
A('')
A('**Deux octets sont morts.** `+0x00` (la donnée « en `0xE111E` ») n’est **lu par aucun site** —')
A('vérifié quatre fois : aucun `[r4]` sans déplacement, aucun `[r4+#0]`, aucun handle voisin (`word_1418`')
A('n’accède qu’à `+8`, `word_141A` qu’à `+8`), aucune arithmétique de pointeur. `+0x04` (→ `byte_C2BB`)')
A('est écrit et **jamais relu**. **Aucun des deux ne peut donc désactiver quoi que ce soit.**')
A('')
A('**Un seul octet coupe la boucle : `+0x0B` = `0xE1129`.** Et il ne fait **rien d’autre** :')
A('')
A('| variable touchée | valeur forcée | conséquence |')
A('|---|---|---|')
A('| `word_DB66` | `0` | consigne nulle (les **deux** chemins de calcul, `l.196410` et `l.196439`) |')
A('| `word_DB64` | `0` | terme remis à zéro |')
A('| `word_D492` | `0` | valeur interpolée effacée |')
A('| `word_DB6C`, `word_DB6E` | `0` | terme accumulé effacé |')
A('')
A('Les images `word_D4xx` tombent à zéro **par conséquence** (elles recopient `DB66`/`DB68`), pas par action')
A('directe. **`+0x0B` n’a que 2 sites, dans une seule fonction (EA `0xBB51E` et `0xBB558`, seg015) : c’est la')
A('portée la plus étroite de tout le bloc.**')
A('')
A('#### Portée mesurée, octet par octet (nombre de lectures et segments atteints)')
A('')
A('| octet | miroir | lectures | segments |')
A('|---|---|---|---|')
A('| `+0x0B` | *(test direct)* | **2 sites** | seg015 seul, **1 fonction** |')
A('| `+0x27` | `byte_C2BA` | **61** | s13 = 11, s14 = 37, s15 = 7, s16 = 5, s17 = 1 |')
A('| `+0x0E` | `byte_C2B7` | **29** | s13 = 14, s14 = 1, s15 = 10, s16 = 4 |')
A('| `+0x10` | `byte_C2B6` | **24** | s13 = 5, s14 = 6, s15 = 11, s17 = 2 |')
A('| `+0x03` / `+0x15` | `C2BD` / `C2C0` | 12 / 12 | s14-s15-s16 / s14-s15-s16 |')
A('| `+0x17` / `+0x1A` | `C2B8` / `C2D1` | 8 / 8 | s13-s14-s16 / s16 |')
A('| `+0x0A` | `byte_C2C9` | 7 | s13 = 5, s15 = 2 |')
A('| `+0x16` / `+0x18` / `+0x26` | `C2BF` / `C2B4` / `C2C4` | 6 / 6 / 6 | s14 / s13-s14-s15-s16 / s14-s15-s16 |')
A('| `+0x01` / `+0x02` / `+0x19` | `C2B1` / `C2C5` / `C2D0` | 5 / 5 / 5 | s13-s16 / s14-s16 / s16 |')
A('| `+0x09` | `byte_C2B0` | 3 | s14 = 2, s16 = 1 |')
A('| `+0x06` / `+0x0F` | `C2B9` / `C2B3` | 2 / 2 | s14 / s15 |')
A('| `+0x1B`…`+0x25`, `+0x28` | 11 miroirs | **1 chacun** | s16 uniquement |')
A('')
A('**Total : 214 lectures** pour les 31 miroirs. **Conclusion nette : le bloc n’est pas « un switch », et les')
A('octets ne partagent pas la même cible.** `+0x0B` est le seul à toucher la boucle d’air ; les autres')
A('touchent la carte `byte_C2B7` (diagnostic, 4 segments), `byte_C2B6` (4 segments), `byte_C2BA` (5 segments).')
A('')
A('**Si une définition de fichiers annonce « EGR off » à `0xE111E`, elle désigne la BASE du bloc. L’octet')
A('réellement lu par le code est `0xE1129` (`+0x0B`).**')
A('')
A('---')
A('')
A('### B.11 — Zone `0xE1129` → `0xE11DD` (+180 octets) : inventaire')
A('')
A('**Douze blocs**, bornés par les pointeurs consécutifs de la table `EA 0xE1400`.')
A('')
A('| handle | EA | taille | contenu | symbole lu | lectures |')
A('|---|---|---|---|---|---|')
A('| `0x141C` | `0xE111E` | 42 o | options — `+0x00` mort, **`+0x01` = interrupteur maître**, `+0x0B` = coupe la boucle d’air | `word_141C` | 9 |')
A('| `0x1F8A` | `0xE1127` | 4 o | `30 01 00 00` | **aucun** | 0 |')
A('| `0x232E` | `0xE112B` | 11 o | octets 0/1 | **aucun** | 0 |')
A('| `0x1F0A` | `0xE1136` | 4 o | `02 03 02 01` | **aucun** | 0 |')
A('| `0x23F4` | `0xE113A` | 14 o | octets 0/1 + `0xC3` final | **aucun** | 0 |')
A('| **`0x141E`** (+ alias `0x2148`) | **`0xE1148`** | **52 o** | **bloc d’options : 97 lectures, offsets `+0x01`…`+0x33`** | `word_141E` | **97** |')
A('| `0x1420` | `0xE117C` | 24 o | **12 × `0xFFFF`** | `word_1420` | 2 (pointeur) |')
A('| `0x1E76` | `0xE1194` | 12 o | 6 × `0xFFFF` | **aucun** | 0 |')
A('| `0x1422` | `0xE11A0` | 23 o | zéros | `word_1422` | 2 (pointeur) |')
A('| `0x1FE6` | `0xE11B7` | 11 o | zéros | **aucun** | 0 |')
A('| `0x1FC8` | `0xE11C2` | 2 o | `0x0000` | **aucun** | 0 |')
A('| `0x1424` | `0xE11C4` | 40 o | **table de 20 valeurs 16 bits** | `word_1424` | 4 (pointeur) |')
A('')
A('**8 handles sur 12 n’ont aucun symbole dans le code** ; `0x2148` est un **alias exact** de `0x141E`.')
A('')
A('#### Les deux offsets dominants de `0xE1148`')
A('')
A('| offset | sites | effet |')
A('|---|---|---|')
A('| **`+0x0A`** | **16** (seg015) | **sélecteur d’échelle** : `r8 = 0` si `== 1`, sinon **`r8 = 0x2710` (10 000)**. Valeur `0x30` ⇒ échelle 10 000 partout |')
A('| **`+0x14`** | 6 (4 segments) | **sélecteur à 4 états** (`#2`, `#3`, `#4` → même cible), sinon `r5 = 0x0F − r4` |')
A('| `+0x09` / `+0x06` | 8 / 4 | sélecteurs de type (`#4`, `#2`, `#1`) |')
A('| `+0x0C` | 5 (seg014) | variante : 5 sauts conditionnels |')
A('')
A('#### Le diagnostic, sous forme de tables')
A('')
A('- `sub_BE2BA` construit une **réponse diagnostic** (`movb rl4, #42h` + identifiant + 4 octets), avec')
A('  découpage en groupes de 32 (`0x00 0x20 0x40 0x60 0x80 0xA0 0xC0 0xE0`).')
A('- Marqueur `0xFF` ⇒ valeur lue dans `0xE117C` (que des `0xFFFF` = « pas de valeur »).')
A('- Marqueur `0xFE` ⇒ valeur lue dans `0xE11A0` (que des zéros). Le marqueur vient de **RAM `0xDC2C + index`**.')
A('- `sub_BEF66` scanne les **20 entrées** de `0xE11C4` après un **test de masque** (`and r4, r5`).')
A('- `loc_CF1F0` (seg016) **recopie ces 20 mots en RAM `0xCC54+4i`** via `sub_CFEFA` (conversion).')
A('  ⇒ `0xE11C4` est une **table de 20 valeurs 16 bits indexées par position**, pas une table d’identifiants.')
A('- Juste après, `loc_CF216` parcourt **96 entrées** depuis `0xCCB2` (`cmp r3, #60h`) = **table de défauts**.')
A('')
A('#### Verdict sur les hypothèses FAP')
A('')
A('**Aucune donnée FAP dans cette zone** : pas de masse de suie (g), pas de pression différentielle (hPa),')
A('pas de kilométrage. Ce qu’elle contient réellement = **options de variante** + **tables de service du')
A('diagnostic**. La porte d’entrée vers les seuils FAP est la **table de défauts `0xCCB2`** (96 entrées),')
A('dont les enregistrements pointent en général vers les seuils de surveillance.')
A('')
A('---')
A('')
A('### B.12 — ★ ERRATA de B.11 + seconde passe : 138 lectures dans la zone')
A('')
A('#### Deux raisons pour lesquelles `0xECCB2` est vide')
A('')
A('1. **`0xCCB2` est une adresse RAM** (`mov r4, #0CCB2h`), pas une EA de ROM : la table de défauts est')
A('   **construite en RAM** au runtime à partir de `0xCC54` (`cmp r8, #0CCA4h`).')
A('2. **La copie `0xE` est tronquée** : les données s’arrêtent à **EA `0xEBFB9`**, puis `0xEC000–0xF0000`')
A('   est constitué de **16 384 octets de `0xC3`**. En revanche **`EA 0xFCCB2` (copie `0xF`) contient')
A('   des données** : `f0 fe 0f 00 21 8f 04 60 50 7e 00 00 41 8f 06 60 0a cc 0f 00 ff ff ff ff`.')
A('')
A('**Différence entre les deux copies : 14 147 octets**, dont **14 octets isolés seulement sous `0xEBFFF`**')
A('(`0xE0FF6`, `0xE0FFC`, `0xE434D`, `0xEBCFC`…) et **14 133 octets dans `0xEC000–0xEFFFF`.')
A('⇒ la copie `0xF` possède **≈ 14 Ko de données en plus**. Aucune structure au format 1-D/2-D connu')
A('(18 détections, toutes faux positifs) : ce n’est **pas** de la calibration cartographique.')
A('')
A('#### Errata : 8 handles n’existent pas')
A('')
A('La table de pointeurs compte **exactement 1305 entrées** = handles **`0x1400` → `0x1E30`**.')
A('Les handles `0x1F8A`, `0x232E`, `0x1F0A`, `0x23F4`, `0x1E76`, `0x1FE6`, `0x1FC8`, `0x2148` cités en B.11')
A('sont **des artefacts** : au-delà de `0x1E30` la table contient autre chose (`0x0010`, `0x02D5`…).')
A('')
A('| handle | EA | taille corrigée | lectures |')
A('|---|---|---|---|')
A('| `0x141C` | `0xE111E` | 42 o | 36 |')
A('| `0x141E` | `0xE1148` | 52 o | **102 (39 offsets)** |')
A('| `0x1420` | `0xE117C` | **36 o** (18 × `0xFFFF`) | par `pointeur + PID×2` |')
A('| `0x1422` | `0xE11A0` | **36 o** (18 × `0x0000`) | par `pointeur + PID×2` |')
A('| `0x1424` | `0xE11C4` | 40 o (20 valeurs) | par `pointeur + index` |')
A('| `0x1426` | `0xE11EC` | 32 o | — |')
A('')
A('**18 entrées = PID `0x00`…`0x11`** : les trois tables sont indexées par identifiant OBD.')
A('')
A('#### Seconde passe : 138 lectures, 89 switch / 49 donnée')
A('')
A('| groupe | offsets de `0xE1148` | sites | effet |')
A('|---|---|---|---|')
A('| **masque 32 bits** | **`+0x15 +0x16 +0x17 +0x18`** | 4 | `andb byte_D98E…D991, octet` puis recomposition en `word_D3CE` → **4 octets = un seul filtre 32 bits** |')
A('| **sélecteurs 5 états** | **`+0x04` (8), `+0x09` (9), `+0x14` (8)** | 25 | codes `0…4` ; `+0x04` déclenche aussi le service EEPROM `sub_CE9B4` (`#1B2h`, `word_176E`, `#46FEh`) |')
A('| **échelle** | **`+0x0A`** | **17** | `r8 = 0` si `==1` sinon `0x2710` |')
A('| variante | `+0x0C` (6), `+0x0D`, `+0x1B` | 8 | stratégies seg014 |')
A('| masques ponctuels | `+0x1F +0x20 +0x30` | 3 | `andb` sur registres |')
A('| drapeau de fin | `+0x33` | 7 | seg013 + seg015 |')
A('| seg017 | `+0x1C +0x1D +0x2B +0x2C +0x2D` | 6 | couche CAN/tâches |')
A('')
A('**13 offsets jamais lus** : `+0x00 +0x07 +0x0B +0x0E +0x0F +0x10 +0x11 +0x12 +0x13 +0x1A +0x1E +0x27 +0x32`.')
A('')
A('---')
A('')
A('### B.13 — ★ Accès directs ET indirects à la zone : balayage exhaustif (7 pistes)')
A('')
A('**Le segment `seg019` (`EA 0xF0000`+) contient bien du CODE** (labels `loc_FC0EA`, `loc_FC142`…).')
A('La région non dupliquée de 14 Ko n’est donc **pas** de la calibration. Les seules **données** que le')
A('code y lit sont des cellules nommées, atteintes par `extp` : `byte_FBEF9`, `byte_FBEFA`,')
A('`word_FBF38`/`word_FBF3A`, `byte_FEC00`/`byte_FEC01`.')
A('')
A('| piste d’accès indirect | méthode | résultat |')
A('|---|---|---|')
A('| immédiats `#111Eh #1129h #1148h #117Ch #11A0h #11C4h` | balayage du listing entier | **0 occurrence** |')
A('| repointage des mots-handles | recherche d’écritures sur `word_141C/141E/1420/1422/1424` | **0 écriture** |')
A('| handle passé à une routine (1541 sites) | fenêtre de 6 lignes avant `calls` | 6 candidats → **6 faux positifs** (le vrai handle est chargé 3-4 lignes après : `word_1994`, `word_19B6`, `word_1DCA`) |')
A('| `sub_CE9B4` (686 appels) | relevé des `r1` | **aucun** de nos handles |')
A('| `extp` / pages | pages utilisées : `0x22 0x24 0x33 0x37 0x3E 0x3F` | **jamais `0x38`–`0x3B`** : le Datensatz n’est jamais ouvert en cross-page |')
A('| **`sub_CE57E` (seg016)** | `mov r3, word_1422 ; add r3, r12 ; mov r3, [r3]` | **indirect réel** : la table est choisie par des **bits en RAM `0xFD21 + code`** (bit 0 → `0xE11A0`, bit 1 → `0xE117C`) ; **voir § B.14 pour le décodage complet (r12 doublé, table RAM `0x0E4E`)** |')
A('| **`l.231375` / `l.231675` (seg016)** | `mov r7, word_1424 ; mov r1, [r7+]` (boucle de 20) et `mov r0, word_1424 ; add r0, r1 ; add r0, r1` | **indirect réel** : la table `0xE11C4` est parcourue par index |')
A('')
A('#### ★ Conséquence sur `0xE11C4` : la plupart des valeurs sont des TROUS')
A('')
A('```asm')
A('mov  r0, word_1424')
A('add  r0, r1')
A('add  r0, r1           ; r0 = base + 2*index')
A('mov  r2, [r0]')
A('cmp  r2, #11h         ; ★ 17')
A('jmpr cc_UGT, loc_CF51E ; valeur > 17 -> ÉCARTÉE')
A('mov  r0, #0E4Eh       ; table RAM')
A('add  r0, r2')
A('add  r0, r2')
A('movb rl2, [r0+]       ; 2 octets par entrée, sentinelle 0xFF')
A('```')
A('')
A('Les seize premières valeurs (`0x0F10`, `0x0F61`, `0x0F80`, `0x0FFA`…) sont **toutes > 17** : elles')
A('sont **écartées** par ce test. Seules les deux entrées `0x0005` et `0x000F` passent le filtre et')
A('deviennent des **index** dans une table courte à `0x0E4E`. Autrement dit, **cette table de 20 mots')
A('n’est pas indexée par position : c’est une liste de valeurs dont 18 sont des marqueurs hors bornes.**')
A('')
A('**Conclusion générale** : les **octets d’option** de la zone sont lus **directement** (138 sites) ;')
A('les **trois tables** (`0xE117C`, `0xE11A0`, `0xE11C4`) sont lues **uniquement indirectement**, par')
A('index, avec un sélecteur en **RAM `0xFD21`**. Aucune autre voie d’accès n’existe : sept pistes')
A('vérifiées, toutes négatives sauf celle-là.')
A('')
A('*Données : `acces_indirects_zone.csv`.*')
A('')
A('---')
A('')
A('### B.22 — ★★★★ LE DICTIONNAIRE identifiant → adresse RAM (356 entrées, page `0x90000`)')
A('')
A('**C’est le chaînon final.** À `EA 0x91202` une table de **356 entrées** (`0x0164`) :')
A('')
A('| EA | contenu |')
A('|---|---|')
A('| `0x91202` | `0164` = **356** = nombre d’entrées |')
A('| `0x91204` – `0x914CA` | **356 identifiants triés croissants**, `0x0004` → `0xE4EE` |')
A('| `0x914CC` – `0x91791` | **356 adresses RAM** parallèles |')
A('| `0x91794` … | un 3e tableau parallèle (`FF1C`, `C6CC`, `C476` …) non décodé |')
A('')
A('Accès dans le code : `sub_B7FAC` → `sub_CFEFA` (page `0x24` = `0x90000`) = **recherche dichotomique**')
A('de l’identifiant dans le tableau trié, puis lecture des tableaux parallèles.')
A('')
A('#### Vérification par nos ancres déjà établies')
A('')
A('| identifiant | adresse RAM | grandeur | statut |')
A('|---|---|---|---|')
