A('| `0x0F02` | `0xC3B0` | **température carburant** | ancre établie ✔ |')
A('| `0x0F10` | `0xC42E` | **régime moteur** | ancre établie ✔ |')
A('| `0x0F65` | `0xC3C2` | **RCO EGR** | ancre établie ✔ |')
A('| `0x0F8C` | `0xC6A2` | **charge %** | ancre établie ✔ |')
A('| `0xE4D2` | `0xC5A8` | **masse d’air / tour** | ancre établie ✔ |')
A('')
A('**Six ancres indépendantes tombent juste** ⇒ le tableau est bien identifiant → adresse RAM.')
A('Plage couverte : `0xC228` → `0xFF1C`, **334 adresses distinctes** pour 356 identifiants (quelques alias).')
A('')
A('#### ★ Le groupe EGR, enfin nommé')
A('')
A('| identifiant | RAM |')
A('|---|---|')
A('| **`0x0E80`** | **`0xC4B6`** |')
