A('### B.23 — ★★★ `C6A2` = la CHARGE, et le retour aux capteurs par les DTC')
A('')
A('#### 1. `C6A2` (identifiant `0x0F8C`) = charge moteur')
A('')
A('C’est le **2ᵉ axe** de la famille de cartes « régime (`C42E`) × charge (`C6A2`) » **et** la **mesure** d’une')
A('boucle fermée dont la consigne est `C628`. Ce n’est pas un capteur : c’est une grandeur **calculée,')
A('plafonnée, filtrée**. Aucun DTC ne la surveille ; elle n’apparaît que comme **variable de contexte**')
A('(P1003, P1107, P1429, P1517).')
A('')
A('**Preuves :**')
A('')
A('1. **Axe de cartes** — 11 cartes : `0xE10BA` (16 pts, 0→7000), `0xE10DE` (8 pts, 500→12000), `0xE13C6`,')
A('   `0xE2AEE`, `0xE5468`, `0xE54F2`, `0xE5602`, `0xE5610`, `0xE609A`, `0xE6102`, `0xE61B2`, `0xE622E`,')
A('   `0xE627A`, `0xE62C6`, `0xE7DAC`, `0xE8E12`, `0xE8EE0`, `0xEAFBA`, `0xEB6CE`.')
A('2. **Structure de carte** — `EA 0xE2ADC` (handle `0x14CE`) :')
A('   `[C42E][0007][02EE 03E8 0514 05DC 07D0 0A28 1388][C6A2][0007][01F4 05DC 1770 1B58 1F40 2328 2710]`')
A('   → régime 750…5000 tr/min, charge 500…10000.')
A('3. **Mesure de boucle** — `sub_D4C1A` (l.241445) : `r13 = C91C = C42E`, `r14 = C94C = C6A2`,')
A('   `unk_2EE2` (2-D), puis `mul r4, word_C7E0` / `divl #2710h` ⇒ résultat en **% de 10000**.')
A('4. **Écart consigne − mesure** — `loc_A3FDA` (l.156386) : `r4 = word_C628 − word_C94C`.')
A('   `C628` = **consigne**, écrite à `loc_B2818` (l.182038). Seuils de bascule en `[cal+#14h..#18h]`.')
A('5. **Producteur borné** — bloc `seg015 0xB71xx–0xB73xx` : `r9` borné ≥ 0 (l.189610), plafonné par')
A('   `[word_142C+#0Eh] + word_C690` (l.189624), `r8 = C6A0 + r9`, machine d’état `C948` ∈ {1,2,3} avec')
A('   compteurs `C0EE`/`C0F0`/`DAF8`, puis `C94C ← r9` → **`C6A2 ← C94C`** (l.189839).')
A('   `word_C690` = **sortie de la carte de limite de fumée** : `unk_1D50(0x1B40 = 0xE8444, C42E, C3E6)`.')
A('')
A('⇒ **charge = air admis mesuré, plafonné par la limite de fumée, filtré, maintenu par machine d’état.**')
A('Unité : mêmes décades que les variables d’air ⇒ **mg d’air/tour ×10** (0…12000 ⇔ 0…1200 mg) —')
A('*confiance moyenne* (une plage ne prouve pas une grandeur).')
A('')
A('#### 2. Les trois variables d’air, enfin distinctes')
A('')
A('| RAM | identifiant | rôle | preuve |')
A('|---|---|---|---|')
A('| `C3E6` = `C3E8` = `C3E2` | **`0x0F30`** | **air admis mesuré** (3 miroirs) | `loc_97324` l.131318-131322 : `[word_15F0+#4]` → `C3E8`, `C3E6`, `C3E2` |')
A('| **`C6A2`** | **`0x0F8C`** | **charge retenue** (axe + boucle) | cf. ci-dessus |')
A('| `C5A8` | `0xE4D2` | masse d’air par tour | DTC P1429 |')
A('| `C3EC` | *(aucun)* | variante d’air, si `byte_C2C9 < 0x30` | l.181913 vs 181922 |')
A('')
A('#### 3. Règle de tri : identifiant OU constante dans les records')
A('')
A('Les **5 champs** d’un record DTC peuvent porter **un identifiant** (⇒ variable RAM) **ou une constante**.')
A('Sur 93 records : **103 identifiants** seulement sont de vraies variables. Exemples de constantes :')
A('`P0106` → `6463 6968 7270 7574 7776` ; `U0300` → `00C8 0D67 1388 2328` (200, 3431, 5000, 9000) ;')
A('`P0503` → `01F4 F8FF C301`. ⇒ toujours tester la présence dans les 356 du dictionnaire.')
A('')
