A('### B.24 — ★★★★ `C60A` = PRESSION ATMOSPHÉRIQUE · la carte boost limiter `0xE7828` · ERRATA P0470')
A('')
A('#### 1. La carte `EA 0xE7828` = boost limiter = f(Patmo, régime)')
A('')
A('`fo 0x67858` (= `EA 0xE7858`) est **la grille** de cette carte (handle `0x1A44`, ptr `0x7828`) :')
A('')
