A('EA 0xE7840 : [C42E][10] 1000 1250 1500 2000 2500 3000 3500 4000 4500 5000')
A('EA 0xE7858 : grille 10 x 10  (fo 0x67858)')
A('```')
A('')
A('Consommateur (l.174279) : `r12 = word_1A44`, `r13 = word_C940 (= C60A)`, `r14 = word_C91C (= C42E)`,')
A('`unk_1D50` → `sub_9FF46(consigne, limiteur)` → `C946` → **`C614`** (l.174392).')
A('')
A('| Patmo \\ régime | 1000 | 1500 | 2000 | 2500 | 3000 | 3500 | 4000 | 5000 |')
A('|---|---|---|---|---|---|---|---|---|')
A('| 600  | 1000 | 1120 | 1325 | 1375 | 1415 (2.36) | 1455 | 1355 | 1159 |')
A('| 700  | 1000 | 1250 | 1520 | 1605 | 1645 (2.35) | 1635 | 1520 | 1359 |')
A('| 800  | 1040 | 1440 | 1745 | 1835 | 1880 (2.35) | 1830 | 1725 | 1570 |')
A('| 900  | 1170 | 1640 | 1960 | 2070 | 2130 (2.37) | 2045 | 1950 | 1780 |')
A('| 950  | 1240 | 1750 | 2070 | 2200 | 2270 (2.39) | 2200 | 2130 | 1840 |')
A('| 1050 | 1330 | 1850 | 2150 | 2370 | 2370 (2.26) | 2300 | 2150 | 1840 |')
A('')
A('**Preuve** : à régime fixe, valeur / Patmo = **rapport de compression constant ≈ 2.35-2.39** ⇒ l’axe ne')
A('peut être qu’une **pression d’entrée du compresseur** = pression atmosphérique. Valeurs 1000-2370 =')
A('1.0-2.37 bar **absolus**.')
A('')
A('#### 2. `C60A` = pression atmosphérique (hPa) — quatre autres preuves')
A('')
A('1. **Repli en calibration** : `word_C60A ← word_C38E` (l.172644-645), et `word_C38E = [word_1418+8]`')
A('   (l.212327) = **constante de calibration** (capteur absent).')
