A('### B.31 — ★ Deux chaînes résolues : `C78A` = accumulateur d’avance · `C3AE` = `[0xF884]`')
A('')
A('#### 1. `word_C78A ← word_F99E ← r15` = **l’accumulateur d’avance**')
A('')
A('```')
A('l.240948 : word_F99E, r15          r15 = C756+C73E+C74E+C748+C766+C770 (six correctifs)')
A('l.241092 : saturations #7FFFh / #8000h')
A('l.241148 : word_C78A ← word_F99E')
A('l.241149 : calls sub_D4D0A           → r4 = sortie de la carte')
A('l.241152 : add r14, r4              → la sortie SE RAJOUTE à l’avance')
A('```')
A('')
A('⇒ la carte 14 × 18 (`0xE2B62` / `0xE2D5A`) est une **correction d’avance = f(pression `C7C2`, avance `C78A`)**.')
A('')
A('#### 2. `sub_D4D0A` (l.241558) — mécanisme intégral')
A('')
A('```')
A('byte_C2C1 = 1 → r15 = word_14D0 (grid 0xE2B62)   |   3 → r15 = word_14D2 (grid 0xE2D5A)')
A('unk_2F56(r1=0xE5B0, r2=C7C2, r3=word_14D6)   → position X')
A('unk_2F56(r1=0xE5B6, r2=r14 (C78A), r3=word_14D8) → position Y')
A('unk_2FAC(0xE5B0, 0xE5B6, r15)                → valeur interpolée')
A('```')
A('')
A('`0xE5B0` / `0xE5B6` = positions d’interpolation en RAM (et non des adresses de calibration).')
A('')
A('#### 3. `C3AE ← [0xF884]`')
A('')
A('`mov r9, #0F884h` · `mov r9, [r9]` · `sub_C4AAE(word_1548, r9)` · `word_C3AE ← r9` (l.214368-214374),')
A('ainsi que `word_D05A` et `word_C374`. `0xF884` n’est pas un symbole nommé : c’est un **pointeur de')
A('structure** (aussi l.213595, 213974, 217875). Chemins de secours : `C3AE = 0` (l.205130).')
A('')
