A('`loc_AFBE8` : `code = byte_C240 & 0x0F` ; si `> 0x0E` → repli ; **table de sauts `0xA2C + 2×code`** ⇒')
A('`word_1B22` (**EA `0xE835A`, 15 octets**) = `48 · 1 · 2 · 3 · 4 · 0 · 0 · 0 · 0 · 11 · 0 · 0 · 0 · 0 · 0`.')
A('')
A('⇒ **le rapport n’est pas calculé dans le code visible** : soit reçu (`0x349`, non armée :')
A('`byte_C2B7 & 1 = 0`), soit figé au défaut `[word_1658+8]`, soit calculé dans la bibliothèque effacée.')
A('**Test de banc** : relever `byte_C240` en 3ᵉ puis en 5ᵉ à 50 km/h — s’il change, il est calculé.')
A('')
A('#### 4. Protection thermique modulée par la vitesse (`sub_B2A02`)')
A('')
A('`0xE880A` = `[C42E][6][1300 1800 2200 2800 3300 4000] × [C3D2][6][3841 3851 3861 3891 3921 3951]`')
A('(températures **111 → 122 °C**), multipliée par `0xE87EE` = `[C562] → [0 10000 10000 20496 20496 0]`')
A('(×2,05 entre 21 et 70 km/h, **0 à 200 km/h**), le tout `/10000`.')
A('')
A('#### 5. Bloc de paramètres du régulateur (`0xE8C5A`–`0xE8CD0`)')
A('')
A('`0x1B6C` `FFFF·0·41·FFFE` (défaut `0x40DF`) · `0x1B6E` + `0F10·0F08·0F80` · `0x1B70` `0·30000·0·−29968·30000')
A('·0·10000·0` · `0x1B7A`…`0x1B84` table des rampes `1000·820·220·512·1024·1024·9` puis paires `(3840,8)')
A('(4480,8) (2560,8) (0,8)` et `500·500·500·600·600·1152` — **paliers de vitesse mémorisés**.')
A('')
A('---')
A('')
A('### B.43 — Le régulateur est UNE tâche (jeton `0x35C`) · ±1 km/h · **ni SET ni RESUME**')
A('')
A('#### 1. Bornes : l.186853 → 187110 (`scxt CC2_CC27, #35Ch` en l.186919)')
A('')
A('```')
A('C93E = C576 ; C91C = C42E ; D9F8 = C6EA')
A('D9FA = C6EA − C562                ; écart consigne − vitesse')
A('r9   = D9F8 ; D9FC = D9F8 − r9    ; limitation de pente par unk_1E50 (descripteur 1B7A)')
A('D9FE = r9 − C562')
A('r8   = unk_1FE8(taux, &DA0A, &D9FE, r9, C562)   ; rampe')
A('C69A = r8   ; C6EA = r9          ; sortie et consigne appliquée')
A('```')
A('')
A('#### 2. ★★ Le ±1 km/h : `word_1B70 + 6` = **EA `0xE8C86` = 100** (1,00 km/h)')
A('')
A('Comparé à `D9FE` ; au-delà → **moniteur de défaut `0x40DF`** (descripteur `word_1B6C`).')
A('Carte de `0xE8C80` : `+0`=0 · `+2`=30000 · `+4`=0 · **`+6`=100** · `+8`=30000 · `+0x0A`=0 ·')
A('`+0x0C`=10000 (sortie `C69A` en état 1). Les **±2 km/h** ne sont pas en immédiat.')
A('')
A('#### 3. Les quatre descripteurs de taux sont **tous nuls**')
A('')
A('`0x1B72`/`0x1B74` = `0 0 0 0 2` · `0x1B76`/`0x1B78` = `0 0 0 0 8` ⇒ rampe neutre. Le vrai limiteur')
A('de pente est `0x1B7A` = **`1 · 1000 · 820 · 220 · 512 · 1024 · 1024 · 9`** via `unk_1E50`')
A('(l.187004) : **10 / 8,2 / 2,2 km/h/s**.')
A('')
A('#### 4. ★★★ Pas de SET, pas de RESUME')
A('')
A('| question | reponse |')
A('|---|---|')
A('| ecrivain de `D9F8` | **un seul** : `D9F8 <- C6EA` (l.186911) |')
A('| ecrivains de `C6EA` | `sub_AF520` (codage) et `C6EA <- r9` (l.187064) |')
A('| memoire de `C562` comme consigne | **aucune** |')
A('| rappel d une consigne anterieure | **aucun** |')
A('')
A('=> **ni SET (`C562 -> memoire`) ni RESUME** dans ce build. La consigne ne peut valoir que **30000**')
A('(defaut de codage) ou **10000** (etat 1).')
A('')
A('#### 5. ★★★ `C576` et `C93E` sont **structurellement nuls**')
A('')
A('`C576 <- C93E` et `C93E <- C576` (ou `0`) sur les 5 sites d ecriture ; **aucun pointeur vers `0xC576`')
A('ni vers `0xC93E`** => boucle fermee a zero. Consequences : les taux nuls sont toujours retenus ; **la')
A('nervosite ne peut pas se declencher** (test `C93E > 539` impossible => toujours la carte `0xE8BD4`) ;')
A('aucune demande exterieure n entre par `C576`.')
A('')
A('#### 6. La regle « 3e/4e rapport ≥ 50-60 km/h » est **hors ECU** — 4 preuves')
A('')
A('1. `byte_C240` : un seul lecteur, dans le bloc **BVA** (hors circuit si `byte_C2C0 ≠ 1`) ;')
A('2. `byte_C2B7 & 1 = 0` => trame **`0x349` non armee** ;')
A('3. aucune division ne touche `C562` (0 sur 124) ;')
A('4. aucune constante 50/60 km/h dans la tache (seulement **1** et **100** km/h).')
A('')
A('=> condition detenue par le **BSI / commodo** (full-mux), ou par la bibliotheque effacee, ou absente')
A('d un build ou `byte_C2BD & 0x70 = 0`.')
A('')
A('---')
A('')
A('### B.44 — ERRATA de B.43 et **vrai régulateur = tâche `0x340`**')
A('')
A('#### 1. Errata')
A('')
A('| # | B.43 / ETAPE96 | correction |')
A('|---|---|---|')
A('| E1 | « regulateur = tache `0x35C` » | **incomplet** : `0x35C` = sous-tache de consigne ; le regulateur est la tache **`0x340`** (l.183699-186918, ~3200 lignes) |')
A('| E2 | « regle 3e/4e rapport hors ECU » | **partiellement faux** : l autorisation vitesse mini/maxi et regime mini/maxi est **dans l ECU** (bloc `0xE2788`) ; seul le **rapport** reste introuvable |')
A('| E3 | `C576`/`C93E` nuls | valable ; `C93E` = etat de la demande du regulateur |')
A('| E4 | « ni SET ni RESUME » | **a revoir** : la tache `0x340` a un etat de memorisation `D9CE` et des etats 1/2/3/4 (`byte_D9B0`) |')
A('')
A('#### 2. Tache `0x340` : codage et machine d etats')
A('')
A('- `byte_C2BD` (EEPROM de codage, `[word_141C+3]`) : **`0x80` ou `0x01`** = actif (`loc_B36EC`),')
A('  `0x00` = variante `loc_B3CEC`, autre = hors service.')
A('- code d etat 4 bits `byte_D9DF` : bit3 `C2D7`, bit2 `C2D6`, bit1 `C2D8`, bit0 = (`C2D5`==0),')
A('  force par `C8EE`/`FD5A.15` -> **table de 16 entrees `0xA7A`** (offsets `fo 0x60A7B`,')
A('  dupliques `0x70A7B` : `3898 39AA 396A 3AB8 3A48 39CA 3A12 3A36 3BFA 3848 3BBC 39B4')
A('  3B06 3CB4 3B68 3CC4`) -> gestionnaires `0xB38xx`-`0xB3Cxx`.')
A('- `byte_D9B3` = **cause de refus** : `0x85` defaut, **`0x86` vitesse mini/maxi**, **`0x87`/`0x88`')
A('  regime maxi/mini**, `0x89` demande insuffisante, `0x8A` incoherence de demande, `0x8E` coupure.')
A('')
A('#### 3. ★★ Bloc d autorisation `word_14B0` = EA `0xE2788`')
A('')
A('`+00` **2500** (25,00 km/h mini) - `+02` **25000** (250 km/h maxi) - `+04` **1000** (tr/min mini) -')
A('`+06` **4500** (tr/min maxi) - `+08` 2560 (ecart de demande) - `+0A` 768 (demande mini) -')
A('`+0C` 4000 - `+0E` 1000 (offset de memorisation -> `D9E0`).')
A('')
A('#### 4. Lois de rampe des etats internes `byte_D9B0`')
A('')
A('etat 2 (l.185468) : `D9BC = 2500*C562/10000 + 5000` ; etat 3 (l.185722) : `D9BC = 500*C562/10000')
A('+ 400` ; puis `D9C0 = D9BC/50`. Parametres : `0xE27B6` (`500`, `400`) et `0xE27C2` (`2500`, `5000`).')
A('')
A('#### 5. Rapport engage : ce qui est exclu')
A('')
A('- division `C91C/C562` : **0 site** (124 divisions, fenetre 18 lignes, sur `C91C`, `C562`, `C42E`,')
A('  `C3FC`, `C578`, `C3FA`) ; multiplication `C562*K` : **0** ; carte 2-D a axe vitesse : **0 sur 66**.')
A('- seules courbes a axe vitesse : `0xE4FA4` (n=8, h `0x18C4`), `0xE87EE`, `0xE869C` (n=6).')
A('- site metier : l.156549 -> `unk_1D36(h 0x18C4, C562)` combine a une correction de charge ->')
A('  `word_D1E6` (correction dependante de la vitesse).')
A('- piste : chercher la **selection de courbes par index** `mov r12, [table + 2*index]`, `index` 0-6.')
