A('### B.46 — Gangberechnung : la chaine complete du rapport engage')
A('')
A('#### 0. ERRATA E6/E7/E8')
A('- E6 : « aucune division ne combine regime et vitesse » est FAUX. La division est en')
A('  l.232301 (sub_CF774). Le balayage l a ratee car le motif etait (div|divu|divl) et non divlu.')
A('- E7 : « le rapport n est pas calcule » est FAUX (confusion non actif / non calcule).')
A('- E8 : C576/C93E ne sont pas nuls : c est le ratio V/N filtre (r5 = 2e registre de retour de')
A('  unk_24BA). Toute l etape 98 section 2.5 est a jeter.')
A('')
A('#### 1. Ratio : V x 256 / N (l.232289-232321)')
A('')
A('    r0 = C42E (regime) ; si 0 -> ratio 0')
A('    MDL = C578 (vitesse) x 256 ; divlu r0 ; saturation = [word_1470+0Eh] = 2560')
A('    unk_24BA(r2, gain word_185C, etat C56A) -> r5 = ratio filtre -> C93E -> C576')
A('')
A('word_1470 -> 0xE225A ; word_185C -> 0xE4B70. 2560 = borne haute de la derniere fenetre de la')
A('table de rapports : coherence croisee.')
A('')
A('#### 2. loc_B0000+2 = Gangberechnung, table word_1A9A -> 0xE81A4')
A('')
A('Codes (octets +0..+5) : 01, 0x0B (point mort), 02, 03, 04, 05. Quatre mots par rapport :')
A('[borne basse][drapeau a][drapeau b][borne haute] ; bit 0x40 = incertitude (hysteresis, r13 =')
A('rapport precedent). Bandes : 1re <202 ; neutre 234-338 ; 2e 338-559 ; 3e 559-826 ; 4e 826-1116 ;')
A('5e 1116-2560.')
A('')
A('Appel l.177478, conditionne par byte_C2C0 == 1 ; sinon branche trame boite')
A('(unk_1D7E(#0C83E, word_1B24)).')
A('')
A('#### 3. Escalier Gangstufen en N/V x100 : 0xE80C4 -> 0xE8164')
A('')
A('7 enregistrements de 10 mots, escaliers de 6 marches. Les deux derniers sont quasi identiques')
A('(10500 7000 4600 3500 2700 / 10500 7000 4500 3500 2700) = seuil d entree / seuil de sortie')
A('(hysteresis). Cellules : 1A8A->0xE8084, 1A8C->0xE80A0, 1A8E->0xE816C, 1A92->0xE8188,')
A('1A9A->0xE81A4, 1AA0->0xE81E2.')
A('')
A('#### 4. Chaine de bout en bout')
A('')
A('C42E, C578 -> divlu (l.232301) -> filtre -> C93E/C576 -> loc_B0000+2 (table 0xE81A4) ->')
A('byte_C330 (+ byte_D398 0-7) -> switch 0xA62 (1B54/1B56/1B58/1B64/1B5C) -> D9A2 -> D3EC/D3DA ;')
A('et refus regulateur 0x92 si code 0x0B/0x0C.')
A('')
A('Verrou restant : byte_C2C0 == 1 (octet de telecodage) — a chercher dans l EEPROM de codage.')
