A('  détectés automatiquement : le balayage n’est pas exhaustif (des records se confondent avec des courbes) ;')
A('- `0xCF5EC` lu en page `0x3A` → **non** ; la bonne règle est `0xE0000 | (p & 0x3FFF)`.')
