A('### B.19 — ★★★ Les codes DTC **en clair** : record de 16 mots = `[DTC][8 mots][5 identifiants][classe][seuil A][seuil B][0xC3]`')
A('')
A('**LA BONNE RÉSOLUTION D’ADRESSE** (elle débloque tout) : les pointeurs des 96 listes se résolvent par')
A('`EA = 0xE0000 | (pointeur & 0x3FFF)`, c’est-à-dire **en offset dans la page de 16 Ko en tête du segment E**')
A('— et non par page `0x3A` comme je l’avais supposé à l’étape 70.')
A('')
A('```')
A('EA 0xE3730 : 0000 0045 1169 0000 0000 0000 0000 0000')
A('EA 0xE3740 : 0000 0000 0000 0F10 0F65 0FF8 0FF9 0F80')
A('EA 0xE3750 : 0003 C3FF 1170 0000 0000 0000 0000 0000')
A('```')
A('')
A('| offset | contenu | exemple `P1169` |')
A('|---|---|---|')
A('| `+0x00` | **code DTC en clair** (16 bits) | `1169` = **P1169** |')
A('| `+0x02` … `+0x11` | 8 mots de données (16 o) | `0000` ×8 |')
A('| `+0x12` … `+0x1B` | **5 identifiants de grandeurs** (`0x0Fxx`) | `0F10 0F65 0FF8 0FF9 0F80` |')
A('| `+0x1C` | **classe** (0…3) | `03` |')
A('| `+0x1D` | **seuil A** | `00` |')
A('| `+0x1E` | **seuil B** (`0xFF` = jamais de guérison) | `FF` |')
A('| `+0x1F` | **sentinelle `0xC3`** | `C3` |')
A('')
A('⇒ **record de 32 octets = 16 mots**, et le suivant commence immédiatement : `0xE3754` = `1170` (P1170).')
A('Une **variante de 16 octets** existe aussi (28 pointeurs vérifiés).')
A('')
A('#### Les 43 records validés (extrait)')
A('')
A('| index | EA | DTC | classe | seuil A | seuil B | identifiants |')
A('|---|---|---|---|---|---|---|')
A('| 0 | `0xE2372` | **P1517** | 1 | 0 | 2 | `0F10 0F08 0F65 0F8C 0F7F` |')
A('| 0 | `0xE2FCA` | **P1101** | 2 | 2 | 2 | `0F10 0F41 0F40 0F80 0F01` |')
A('| 4 | `0xE3734` | **P1169** | 3 | 0 | 255 | `0F10 0F65 0FF8 0FF9 0F80` |')
A('| 5 | `0xE3754` | **P1170** | 3 | 0 | 255 | `0F65 0F01 0FF8 0FF9 0F80` |')
A('| 6 | `0xE3282` | **P0190** | 3 | 0 | 4 | `0F10 0F64 2066 0FFC 0EA5` |')
A('| 9 | `0xE36AC` | **P0560** | 2 | 2 | 2 | `0F10 0F01 0F65 0F08 0F7F` |')
A('')
A('#### ★ Conséquence : la question ouverte sur `word_1424` est RÉSOLUE')
A('')
A('Les identifiants de ces records (`0F10 0F65 0F7F 0F64 0F08`…) sont **exactement l’alphabet de `word_1424`**')
A('(`0xE11C4`). Donc les 20 valeurs de `0xE11C4` sont des **identifiants de grandeurs**, et non des adresses :')
A('`0x0Fxx` = *« identifiant de la mesure n° 0Fxx »*. Le test d’intersection vide de l’étape 70 portait sur les')
A('**pointeurs**, pas sur ces identifiants — d’où le faux négatif.')
A('')
A('*Données : `dtc_records_valides.csv` (43 records 32 o validés) et `dtc_records_32o.csv` (1 277 candidats).*')
