A('')
A('### B.18 — ★★ Les CINQ conditions de maintien d’un défaut (algorithme complet)')
A('')
A('Le désassemblement de `loc_CF0B6` … `loc_CF14E` (l. 231240-231300) donne l’algorithme exact qui décide')
A('si un enregistrement de défaut **reste** en mémoire ou est **supprimé**. `r3` = enregistrement,')
A('`r0` = `[0xCCB2 + 2·code]` = descripteur du code.')
A('')
A('| # | condition | ligne | sinon |')
A('|---|---|---|---|')
A('| 1 | `descr[+0x00]` bit 0 **doit être 0** (validité du code) | 231252 | supprimé |')
A('| 2 | **classe** `descr[+0x1C] & 3` **< 2** ⇒ il faut `enr[+1]` bit 0 **= 1** ; **≥ 2** ⇒ il faut bit 0 **= 0** | 231257-231268 | suprimé |')
A('| 3 | `enr[+7]` : `0` ⇒ supprimé ; `1` ⇒ bit 3 de `enr[+1]` doit être 0 ; `> 1` ⇒ il doit être 1 | 231270-231283 | supprimé |')
A('| 4 | si `enr[+1]` bit 6 posé ⇒ `enr[+6]` doit **égaler** `word_142A + 9` (octet de **variante/codage**) | 231284-231289 | supprimé |')
A('| 5 | `enr[+4] <= descr[+0x1D]` | 231290-231293 | supprimé |')
A('| 6 | `enr[+5] <= descr[+0x1E]` (si `descr[+0x1E]` = 0, on prend **1**) | 231294-231299 | supprimé |')
A('')
A('**Corrections aux étapes 69 et 71 :**')
A('')
A('- `0xCCB2 + 2·code` n’est **jamais écrit** en marche : les **13 sites** du firmware le **lisent** seulement ;')
A('  il est rempli une fois au démarrage (l. 231171-231180).')
A('- `descr[+0x1C]` n’est **pas** un seuil : c’est un **code de classe 0…3** (bits 0-1) doublé d’un **masque**')
A('  (bits 3-7, `andb #0F8h` l. 231777). Les **seuils** sont `+0x1D` et `+0x1E`.')
A('')
A('⇒ **Deux seuils numériques par code de défaut** (`+0x1D`, `+0x1E`) comparent les compteurs `enr[+4]` et')
A('`enr[+5]` ; et **un octet de variante** (`word_142A + 9`) filtre les défauts selon le **codage** du calculateur.')
A('')

A('')
