A('')
A('### B.17 — ★★ Verrou DPP levé : les 1 277 pointeurs sont des **adresses RAM**, une plage privée par code')
A('')
A('#### 1. La configuration de pages du firmware (enfin établie)')
A('')
A('```asm')
A('scxt DPP0, #0        ; l. 96805')
A('scxt DPP1, #0        ; l. 96806   <-- DPP1 = 0, PAS 1')
A('scxt DPP2, #2        ; l. 96807')
A('scxt DPP3, #3        ; l. 96808')
A('```')
A('')
A('⇒ l’espace 16 bits couvre **EA `0x00000`–`0x0FFFF`** (64 Ko de RAM/périphériques internes).')
A('Les pages flash ne sont ouvertes que **localement**, six fois : `DPP0 = 0x22` (l. 96530, 97450, 98358,')
A('98477, 98515, 111273), `DPP1 = 0x21` (l. 98479), `DPP2 = 0x24` (l. 233064, 233137), `DPP2 = 0x48` (l. 111665).')
A('Le reste du temps, les DPP sont **sauvegardés/restaurés** depuis `word_C1DA` / `word_C1DC`')
A('(`mov word_C1DA, DPP0`, l. 112878 ; `scxt DPP0, word_C1DA`, l. 125397 ; écriture calculée l. 199535).')
A('')
A('#### 2. Conséquence : les listes pointent la **RAM**')
A('')
A('Aucune des routines qui consomment les 96 listes (`sub_CEC02`, le bloc l. 231157-231530) ne modifie un DPP.')
A('⇒ un pointeur `0xA1A8` vaut **EA `0xA1A8`**, c’est-à-dire une **variable RAM**, pas une adresse flash.')
A('Mon test de l’étape 70 (« le contenu à `fo 0xA1A8` est du code ») comparait donc une adresse RAM à un')
A('offset de fichier : l’hypothèse à réfuter était mal posée, le résultat est maintenant net.')
A('')
A('#### 3. Ce que révèle la géométrie des 1 277 pointeurs')
A('')
A('| constat | mesure |')
A('|---|---|')
A('| plages **disjointes** | seules **3 paires sur 4 465** se chevauchent ⇒ **chaque code possède sa plage RAM privée** |')
A('| écart entre pointeurs consécutifs | **6 o** (316×), 12 (132×), 4 (92×), 2 (83×), 32 (78×), 10, 8, 36, 28, 24 |')
A('| taille des blocs | des **enregistrements de 6 / 12 / 32 octets** |')
A('')
A('| code | plage RAM | nb d’enregistrements |')
A('|---|---|---|')
A('| 0 | `0xA1A8`–`0xBAB0` | **139** |')
A('| 1 | `0x2372`–`0x2736` | 10 |')
A('| 2 | `0x9462`–`0x94C8` | 14 |')
A('| 3 | `0xBAB6`–`0xBB9A` | 11 |')
A('| 7 | `0x4A70`–`0x4A96` | 3 |')
A('| 8 | `0x94CE`–`0xA128` | 49 |')
A('')
A('⇒ **chaque code de défaut possède, en RAM, une table privée d’enregistrements de 6 / 12 / 32 octets** ;')
A('la liste du Datensatz en donne l’index. Ces tables sont **construites au démarrage** à partir de la calibration :')
A('c’est là, et non dans la liste, que se trouvent les seuils.')
A('')
A('#### 4. Retour sur `word_1424` (`0xE11C4`)')
A('')
A('Les valeurs `0x0F10 0x0F61 0x0F80 0x0FFA …` appartiennent au **même espace** : ce sont des **adresses RAM**')
A('de la page `0x0F00`. Donc les « trous » constatés à l’étape 67 ne sont pas des marqueurs : ce sont')
A('**les entrées qui ne sont pas des codes ≤ 17** — seules `0x0005` et `0x000F` en sont. La lecture « tableau mixte »')
A('est la bonne.')
A('')

A('')
A('---')
A('')
A('### B.16 — Réseau code de défaut → listes de pointeurs : 96 listes, 1 277 pointeurs (et 3 hypothèses réfutées)')
A('')
A('**Ce qui est acquis.** La table de 96 pointeurs de `EA 0xCF5EC` (page `0x33`) donne 96 structures')
A('**distinctes** dans le Datensatz, `0xE1426`–`0xE1E20`, soit **2 554 octets**, et chacune est une')
A('**liste de pointeurs de 2 octets** (décalages croissants, ce qui est l’auto-validation : une suite')
A('croissante ne peut pas être du code).')
A('')
A('| mesure | valeur |')
A('|---|---|')
A('| listes | 96 (95 non vides) |')
A('| pointeurs | **1 277**, tous distincts |')
A('| plage des pointeurs | `0x11EC` – `0xBB9A` |')
A('| longueur des listes | 2 o (43 listes → 1 seul pointeur) … 278 o (`EA 0xE1CF4`, code 0) |')
A('| moyenne | ≈ 13 pointeurs par code de défaut |')
A('')
A('⇒ **un code de défaut donné est associé à ≈ 13 grandeurs surveillées.** C’est le réseau')
A('« défaut ↔ mesures » du calculateur.')
A('')
A('**Trois hypothèses testées ce jour, trois réfutées** (consignées pour ne pas les rejouer) :')
A('')
A('1. « Ces listes contiennent des identifiants `0x0Fxx` comme `word_1424` » → **faux** : intersection')
A('   **vide** (0 des 20 identifiants de `0xE11C4`). L’alphabet `0x0Fxx` et les listes de défauts sont deux mondes.')
A('2. « Les blocs pointés suivent une trame fixe de 32 octets terminée par la sentinelle `0xC3` » → **faux** :')
A('   seulement **16 blocs sur 96** finissent par `0xC3` à `+0x1F` ; les autres valeurs sont majoritairement')
A('   `0x00` (39 blocs).')
A('3. « Les pointeurs sont des adresses linéaires résolubles » → **non tranché** : `0xA1A8` lu à `fo = 0xA1A8`')
A('   donne du code, à `fo = 0xA1A8 + 0x80000` sort du fichier. Il manque **le DPP en vigueur** au point')
A('   d’accès ; `sub_CEC02` n’exécute aucun `scxt DPP`, donc il hérite de son appelant.')
A('')
A('*Données : `defauts_96_listes.csv` (96 listes, 1 277 pointeurs) et `defauts_96_descripteurs.csv`.*')
A('')

A('')
A('---')
A('')
A('### B.15 — ★★ Mémoire de défauts : 7 enregistrements de 22 octets, 96 descripteurs, et le bloc EEPROM de 176 octets')
A('')
A('#### 1. Géographie')
A('')
A('| adresse | taille | rôle | preuve |')
A('|---|---|---|---|')
A('| **`0xE467` – `0xE500`** | **`0x9A` = 154 o = 7 × 22** | enregistrements de défauts | `mov r2, #9Ah` l. 229619 ; `mov r1, #16h ; mulu` l. 229640-229644 |')
A('| `byte_E466` | 1 o | **nombre d’enregistrements courants** (0…7) | l. 229606, 229661, 229896 |')
A('| `byte_E501` | 1 o | **pointeur d’insertion / index du dernier** | l. 229585, 229918, 229938 |')
A('| `byte_E502`, `0xE503 + i` | 1 o | octets annexes du service diag | l. 231679, 231711, 231717 |')
A('| `0xCAD0 + 4·code` | 96 × 4 o | état par code | § B.14 |')
A('| **`0xCCB2 + 2·code`** | **96 × 2 o** | **pointeurs vers les descripteurs** | `mov r1, #0CCB2h` + boucle de `0xC0` = 192 o, l. 231163-231172 |')
A('| `0xCE00` | 96 o | instantané de `0xFD21` | l. 230346 |')
A('')
A('#### 2. Champs de l’enregistrement de 22 octets')
A('')
A('| offset | rôle | preuve |')
A('|---|---|---|')
A('| `+0` | **code du défaut** | `movb rh2, [r3]` l. 229620 ; `cmpb rl2, rl6` l. 229668 |')
A('| `+1` | **octet d’état** (bit 0 = actif, bit 6, bit 2) | `jnb r0.0` l. 229940 ; `jb r0.6` l. 231296 |')
A('| `+2` | **compteur de conditions** (nombre de bits à 1) | boucle `jnb r0.0 / add r4,#1 / shr r0,#1` l. 229947-229958 |')
A('| `+3` | doit être **non nul** (validité) | l. 229695, 229699 |')
A('| `+4` | **compteur de guérison**, comparé à `[descr+#1Dh]` | l. 231251-231257 |')
A('| `+5` | comparé à `[descr+#1Eh]` (0 → 1) | l. 231258-231266 |')
A('| `+6` | comparé à `[descr+#1Ch]` **et** à `word_142A+9` (bloc Datensatz) | l. 231273-231282 |')
A('| `+7` | seuil `1` / `>1`, aiguillé par le bit 3 | l. 231285-231292 |')
A('| `+8` … `+21` | non exploités à ce stade (14 o) | — |')
A('')
A('★ **Les seuils de maintien d’un défaut sont donc dans le Datensatz** : `[0xCCB2 + 2·code]` pointe un bloc')
A('dont les champs `+0x1C`, `+0x1D`, `+0x1E` sont comparés aux octets de l’enregistrement.')
A('')
A('#### 3. `sub_CE256` : le service de la mémoire de défauts (commande dans `rh6`)')
A('')
A('| commande | effet | preuve |')
A('|---|---|---|')
A('| `0xFF` | rend le **dernier** enregistrement (`byte_E501`) + son pointeur de descripteur | l. 229583-229599 |')
A('| `0x80`–`0x9F` (masque `0xE0` = `0x80`) | **dump complet : `0x9A` = 154 octets** depuis `0xE467` | l. 229603-229621 |')
A('| `0xCF` | **compte** les défauts (bits de `+2` quand `+1`.0, `+4`=0, `+6`≠0) | l. 229624-229650 |')
A('| `0x00`–`0x1F` | **lit l’enregistrement n° `rl6`** (offset `22 × rl6`) + descripteur `0xCCB2+2·code` | l. 229631-229652 |')
A('| `0x20`–`0x7F`, `0xA0`+, `0xE0`+ | **recherche par code** (`0xEF`/`0xDF` = variantes), bits `r6.12…15` | l. 229663-229740 |')
A('')
A('#### 4. ★ Deux tables de 96 entrées, une par code de défaut, dans la page `0x33`')
A('')
A('| EA | taille | contenu relevé | rôle |')
A('|---|---|---|---|')
A('| **`0xCF5EC`** | 96 × 2 o | `1CF4 1492 1C64 1E0A 15B4 15B6 153E 183E …` — **toutes les valeurs tombent dans la plage des handles `0x1400`–`0x1E30`** | **un bloc de descripteur par code** ; recopié au démarrage à `0xCCB2` (`mov r0, #0B5ECh` + `extp #33h`, `add r2, #0C0h`, l. 231163-231172) |')
A('| **`0xCF6AC`** | 96 × 1 o | `0D 80 FC 00 CC CC F8 7F 00 FC C8 78 1F F8 FC F8 F8 C4 FE …` | **masque par code**, OR-é dans `0xCAD0 + 4·code` à l’init (boucle `r12 = 0xB6AC`, `r13 = 0xCAD1`, `r14 = 0x60`, l. 231221-231232) |')
A('')
A('#### 5. ★ Le bloc EEPROM de la mémoire de défauts — **offset `0x2467`, 176 octets**')
A('')
A('```asm')
A('loc_CF030:')
A('  r1 = word_C45A ; r0 = word_C46A ; extp r0, #1 ; rl0 = [r1]')
A('  r0 = 22 × rl0 ; MDH = 0xE467 + r0        ; ★ enregistrement pointé par l’EEPROM')
A('  ...')
A('  r0 = word_C46A ; shr r0, #2 ; jmpr cc_NZ, loc_CF072')
A('  mov r0, #0E467h ; mov r2, #0B0h ; calls unk_2A9A   ; ★ EEPROM vierge -> 176 o remis à zéro')
A('loc_CF072:')
A('  mov r1, #2467h      ; ★ offset EEPROM')
A('  mov r0, #0B0h       ; ★ 176 octets = 8 × 22')
A('  mov r2, #3')
A('  mov r3, r1')
A('  calls 9, sub_9FFE2  ; ★ lecture/écriture EEPROM')
A('```')
A('')
A('**176 = 8 × 22** : l’image EEPROM réserve **8 enregistrements**, la RAM n’en gère que **7** en marche.')
A('')

A('')
A('---')
A('')
A('### B.14 — ★★ `0xFD21` décodé : 96 octets d’ÉTAT DE DÉFAUT par code, et le mécanisme complet de substitution')
A('')
A('**ERRATA étape 67** : j’avais écrit « table de mots `EA 0xE4E4E` » et « `add r3, r12` avec `r12` = index ».')
A('Les deux sont faux : la table est en **RAM `0x0E4E`** (18 couples d’octets) et `sub_CE57E` exécute')
A('`add r12, r12` **avant** : l’index est doublé. Voici la chaîne complète.')
A('')
A('#### 1. `0xFD21` = 96 octets d’état, un par code de défaut `0x00`–`0x5F`')
A('')
A('| évidence | ligne |')
A('|---|---|')
A('| remise à zéro de 96 octets : `mov r0, #0FD21h` … `mov r2, #5Fh` | 229851-229852 |')
A('| **écrivain unique : `sub_CE9B4`** — `movb rl4, [r4+#0FD21h]`, `andb rl4, rl2`, `orb rl4, rh6`, réécriture | 230438, 230466, 230476 |')
A('| `sub_CE43C` reconstruit les états depuis les enregistrements **RAM `0xE467`** (pas `0x16` = 22 o, `byte_E466` = nombre, fin `0xE501`) et remet `0xFD21 + code` à zéro ; ces enregistrements sont chargés de l’**EEPROM** (bloc de 176 o à l’offset `0x2467`) — voir § B.15 | 229816-229964 |')
A('| copie de travail : `0x0CE00` ← `0xFD21`, 96 octets (`unk_2A9A` = copie avant, débordement exploitée comme `memset`) | 230346-230350 |')
A('| lecture de l’état d’un code dans le service « lire un bloc » : `mov r9, #0FD21h ; add r9, r13` avec `r13 = 16·(code−0x90)`, 7 codes | 206936-206942 |')
A('')
A('#### 2. `sub_CE9B4` = le **poseur d’état de défaut** (686 appels)')
A('')
A('```asm')
A('movb rl4, [r4+#0FD21h]   ; état courant du code rh2')
A('andb rl4, rl2            ; & masque demandé')
A('orb  rl4, rh6            ; | (~masque)  -> pose ou lève')
A('movb [r5+#1], rh0        ; enregistrement 0xCAD0 + 4·code')
A('```')
A('')
A('Deux mémoires mises à jour en parallèle : **`0xFD21 + code`** (bits d’état courants, 1 octet) et')
A('**`0xCAD0 + 4·code`** (enregistrement de 4 octets, `[0]` = état, `[1]` = bits cumulés).')
A('')
A('#### 3. `sub_CE57E` décodé en entier — c’est le pont défaut → valeur de mesure')
A('')
A('```asm')
A('cmp  r12, #11h            ; i = 0…17   (18 mesures surveillées)')
A('jmpr cc_UGT, locret_CE5DE')
A('add  r12, r12             ; ★ i -> 2i')
A('mov  r3, #0E4Eh            ; ★ RAM 0x0E4E : 18 couples de codes')
A('add  r3, r12')
A('movb rl2, [r3+]           ; c1 = 1er code de défaut de la mesure i')
A('movb rh2, [r3]            ; c2 = 2e code (0xFF = aucun)')
A('cmpb rl2, #60h            ; borne : code < 96')
A('jmpr cc_NC, locret_CE5DE')
A('movb rl3, [r3+#0FD21h]    ; ★ état du code c1')
A('andb rl3, #1              ; bit 0 -> word_1422 (0x0000)')
A('andb rl3, #2              ; bit 1 -> word_1420 (0xFFFF)')
A('```')
A('')
A('**Résultat** : la mesure `i` est remplacée par **`0x0000`** si le bit 0 de l’état d’un de ses deux')
A('codes est posé, par **`0xFFFF`** si c’est le bit 1. Les deux tables de 18 mots du Datensatz')
A('(`0xE11A0` = 18 × `0x0000`, `0xE117C` = 18 × `0xFFFF`) sont donc des **valeurs de substitution** —')
A('des drapeaux « mesure disponible / invalide », **pas des lois de calibration**.')
A('')
A('#### 4. Le consommateur : réponse diagnostique `0x42`')
A('')
A('`sub_BE10C` → `sub_942F2` (l.201240) → `sub_CE57E` ; en-tête `0x42` = réponse du service')
A('`readDataByCommonIdentifier`. Dans `sub_BE2BA` (l.201482-201530) :')
A('')
A('```asm')
A('mov  r4, [r8]             ; word_1424[i]')
A('movbz r5, rl6             ; identifiant demandé')
A('cmp  r4, r5')
A('movb rl5, [r4+#0DC2Ch]    ; octet de la table RAM 0xDC2C (8 entrées)')
A('cmp  r4, #0FEh            ; -> pointeur word_1422 + 2·code  (= 0x0000)')
A('cmp  r4, #0FFh            ; -> pointeur word_1420 + 2·code  (= 0xFFFF)')
A('```')
A('')
A('#### 5. Ce qui reste ouvert sur `word_1424` (`0xE11C4`, 20 mots)')
A('')
A('Valeurs : `0F10 0F61 0F80 0FFA 0F8B 0F30 0F32 0F60 0FFC 0F40 0F42 1F5A 1F51 0F64 0F7F 0005 000F 0F65 0F08 0F8A`.')
A('')
A('Elles sont parcourues par `[r7+]` / `[r8+]` (l.201513, l.231375) et **une seule** passe le test')
A('`cmp r2, #11h` d’un des deux consommateurs (`0x0005`, `0x000F`). Deux lectures possibles, non tranchées :')
A('soit des **pointeurs vers la RAM basse `0x0Fxx`/`0x1Fxx`**, soit **deux codages mêlés**. À instruire.')
A('')

A('')
A('*Données : `zone_0xE1129_v2.csv` (74 EAs lues, avec site, segment, nature).*')
